(38498, 2, 'flexible_content_1_heading', 'FAQs Heading Here'),
(38499, 2, '_flexible_content_1_heading', 'field_6aa00910843b2_field_68459c931bfb6'),
(38500, 2, 'flexible_content_1_subheading_tag', 'h3'),
(38501, 2, '_flexible_content_1_subheading_tag', 'field_6aa00910843b2_field_6944fae8b2df1'),
(38502, 2, 'flexible_content_1_subheading', 'This will be FAQs description.'),
(38503, 2, '_flexible_content_1_subheading', 'field_6aa00910843b2_field_6944faebb2df2'),
(38504, 2, 'flexible_content_1_items_0_heading', 'How often should I visit the dentist?'),
(38505, 2, '_flexible_content_1_items_0_heading', 'field_6aa0088362f9a'),
(38506, 2, 'flexible_content_1_items_0_description', 'For many people, a routine dental check-up every six months is a useful general guideline. Your dentist may recommend a different schedule depending on your oral health and individual needs.'),
(38507, 2, '_flexible_content_1_items_0_description', 'field_6aa008bf62f9b'),
(38508, 2, 'flexible_content_1_items_1_heading', 'Is a root canal treatment painful?'),
(38509, 2, '_flexible_content_1_items_1_heading', 'field_6aa0088362f9a'),
(38510, 2, 'flexible_content_1_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(38511, 2, '_flexible_content_1_items_1_description', 'field_6aa008bf62f9b'),
(38512, 2, 'flexible_content_1_items_2_heading', 'What are dental implants?'),
(38513, 2, '_flexible_content_1_items_2_heading', 'field_6aa0088362f9a'),
(38514, 2, 'flexible_content_1_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(38515, 2, '_flexible_content_1_items_2_description', 'field_6aa008bf62f9b'),
(38516, 2, 'flexible_content_1_items_3_heading', 'How can I improve my oral health?'),
(38517, 2, '_flexible_content_1_items_3_heading', 'field_6aa0088362f9a'),
(38518, 2, 'flexible_content_1_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(38519, 2, '_flexible_content_1_items_3_description', 'field_6aa008bf62f9b'),
(38520, 2, 'flexible_content_1_items_4_heading', 'When should children first visit a dentist?'),
(38521, 2, '_flexible_content_1_items_4_heading', 'field_6aa0088362f9a'),
(38522, 2, 'flexible_content_1_items_4_description', 'Children should have their first dental visit when their first tooth appears or by their first birthday, followed by regular dental visits as recommended by their dentist.'),
(38523, 2, '_flexible_content_1_items_4_description', 'field_6aa008bf62f9b'),
(38524, 2, 'flexible_content_1_items', '5'),
(38525, 2, '_flexible_content_1_items', 'field_6aa0088362f98'),
