(38993, 1012, '_flexible_content_1_heading_tag', 'field_6aa00910843b2_field_68459c3a1bfb5'),
(38994, 1012, 'flexible_content_1_heading', 'FAQs Heading Here'),
(38995, 1012, '_flexible_content_1_heading', 'field_6aa00910843b2_field_68459c931bfb6'),
(38996, 1012, 'flexible_content_1_subheading_tag', 'h2'),
(38997, 1012, '_flexible_content_1_subheading_tag', 'field_6aa00910843b2_field_6944fae8b2df1'),
(38998, 1012, 'flexible_content_1_subheading', 'This will be FAQs description.'),
(38999, 1012, '_flexible_content_1_subheading', 'field_6aa00910843b2_field_6944faebb2df2'),
(39000, 1012, 'flexible_content_1_items_0_heading', 'How often should I visit the dentist?'),
(39001, 1012, '_flexible_content_1_items_0_heading', 'field_6aa0088362f9a'),
(39002, 1012, 'flexible_content_1_items_0_description', 'For many people, a routine dental check-up every six months is a useful general guideline. Your dentist may recommend a different schedule depending on your oral health and individual needs.'),
(39003, 1012, '_flexible_content_1_items_0_description', 'field_6aa008bf62f9b'),
(39004, 1012, 'flexible_content_1_items_1_heading', 'Is a root canal treatment painful?'),
(39005, 1012, '_flexible_content_1_items_1_heading', 'field_6aa0088362f9a'),
(39006, 1012, 'flexible_content_1_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(39007, 1012, '_flexible_content_1_items_1_description', 'field_6aa008bf62f9b'),
(39008, 1012, 'flexible_content_1_items_2_heading', 'What are dental implants?'),
(39009, 1012, '_flexible_content_1_items_2_heading', 'field_6aa0088362f9a'),
(39010, 1012, 'flexible_content_1_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>');
INSERT INTO `wp_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(39011, 1012, '_flexible_content_1_items_2_description', 'field_6aa008bf62f9b'),
(39012, 1012, 'flexible_content_1_items_3_heading', 'How can I improve my oral health?'),
(39013, 1012, '_flexible_content_1_items_3_heading', 'field_6aa0088362f9a'),
(39014, 1012, 'flexible_content_1_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(39015, 1012, '_flexible_content_1_items_3_description', 'field_6aa008bf62f9b'),
(39016, 1012, 'flexible_content_1_items_4_heading', 'When should children first visit a dentist?'),
(39017, 1012, '_flexible_content_1_items_4_heading', 'field_6aa0088362f9a'),
(39018, 1012, 'flexible_content_1_items_4_description', 'Children should have their first dental visit when their first tooth appears or by their first birthday, followed by regular dental visits as recommended by their dentist.'),
(39019, 1012, '_flexible_content_1_items_4_description', 'field_6aa008bf62f9b'),
(39020, 1012, 'flexible_content_1_items', '5'),
(39021, 1012, '_flexible_content_1_items', 'field_6aa0088362f98'),
