(39300, 2, 'flexible_content_2_heading', 'FAQs Heading Here'),
(39301, 2, '_flexible_content_2_heading', 'field_6aa00910843b2_field_68459c931bfb6'),
(39302, 2, 'flexible_content_2_subheading_tag', 'h3'),
(39303, 2, '_flexible_content_2_subheading_tag', 'field_6aa00910843b2_field_6944fae8b2df1'),
(39304, 2, 'flexible_content_2_subheading', 'This will be FAQs description.'),
(39305, 2, '_flexible_content_2_subheading', 'field_6aa00910843b2_field_6944faebb2df2'),
(39306, 2, 'flexible_content_2_items_0_heading', 'How often should I visit the dentist?'),
(39307, 2, '_flexible_content_2_items_0_heading', 'field_6aa0088362f9a'),
(39308, 2, 'flexible_content_2_items_0_description', 'For many people, a routine dental check-up every six months is a useful general guideline. Your dentist may recommend a different schedule depending on your oral health and individual needs.'),
(39309, 2, '_flexible_content_2_items_0_description', 'field_6aa008bf62f9b'),
(39310, 2, 'flexible_content_2_items_1_heading', 'Is a root canal treatment painful?'),
(39311, 2, '_flexible_content_2_items_1_heading', 'field_6aa0088362f9a'),
(39312, 2, 'flexible_content_2_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(39313, 2, '_flexible_content_2_items_1_description', 'field_6aa008bf62f9b'),
(39314, 2, 'flexible_content_2_items_2_heading', 'What are dental implants?'),
(39315, 2, '_flexible_content_2_items_2_heading', 'field_6aa0088362f9a'),
(39316, 2, 'flexible_content_2_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(39317, 2, '_flexible_content_2_items_2_description', 'field_6aa008bf62f9b'),
(39318, 2, 'flexible_content_2_items_3_heading', 'How can I improve my oral health?'),
(39319, 2, '_flexible_content_2_items_3_heading', 'field_6aa0088362f9a'),
(39320, 2, 'flexible_content_2_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(39321, 2, '_flexible_content_2_items_3_description', 'field_6aa008bf62f9b'),
(39322, 2, 'flexible_content_2_items_4_heading', 'When should children first visit a dentist?'),
(39323, 2, '_flexible_content_2_items_4_heading', 'field_6aa0088362f9a'),
(39324, 2, 'flexible_content_2_items_4_description', 'Children should have their first dental visit when their first tooth appears or by their first birthday, followed by regular dental visits as recommended by their dentist.'),
(39325, 2, '_flexible_content_2_items_4_description', 'field_6aa008bf62f9b'),
(39326, 2, 'flexible_content_2_items', '5'),
(39327, 2, '_flexible_content_2_items', 'field_6aa0088362f98'),
