(39677, 1015, '_flexible_content_1_heading_tag', 'field_6aa00910843b2_field_68459c3a1bfb5'),
(39678, 1015, 'flexible_content_1_heading', 'FAQs Heading Here'),
(39679, 1015, '_flexible_content_1_heading', 'field_6aa00910843b2_field_68459c931bfb6'),
(39680, 1015, 'flexible_content_1_subheading_tag', 'h2'),
(39681, 1015, '_flexible_content_1_subheading_tag', 'field_6aa00910843b2_field_6944fae8b2df1'),
(39682, 1015, 'flexible_content_1_subheading', 'This will be FAQs description.'),
(39683, 1015, '_flexible_content_1_subheading', 'field_6aa00910843b2_field_6944faebb2df2'),
(39684, 1015, 'flexible_content_1_items_0_heading', 'How often should I visit the dentist?'),
(39685, 1015, '_flexible_content_1_items_0_heading', 'field_6aa0088362f9a'),
(39686, 1015, 'flexible_content_1_items_0_description', 'For many people, a routine dental check-up every six months is a useful general guideline. Your dentist may recommend a different schedule depending on your oral health and individual needs.'),
(39687, 1015, '_flexible_content_1_items_0_description', 'field_6aa008bf62f9b'),
(39688, 1015, 'flexible_content_1_items_1_heading', 'Is a root canal treatment painful?'),
(39689, 1015, '_flexible_content_1_items_1_heading', 'field_6aa0088362f9a'),
(39690, 1015, 'flexible_content_1_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(39691, 1015, '_flexible_content_1_items_1_description', 'field_6aa008bf62f9b'),
(39692, 1015, 'flexible_content_1_items_2_heading', 'What are dental implants?'),
(39693, 1015, '_flexible_content_1_items_2_heading', 'field_6aa0088362f9a'),
(39694, 1015, 'flexible_content_1_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(39695, 1015, '_flexible_content_1_items_2_description', 'field_6aa008bf62f9b'),
(39696, 1015, 'flexible_content_1_items_3_heading', 'How can I improve my oral health?'),
(39697, 1015, '_flexible_content_1_items_3_heading', 'field_6aa0088362f9a'),
(39698, 1015, 'flexible_content_1_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(39699, 1015, '_flexible_content_1_items_3_description', 'field_6aa008bf62f9b'),
(39700, 1015, 'flexible_content_1_items_4_heading', 'When should children first visit a dentist?'),
(39701, 1015, '_flexible_content_1_items_4_heading', 'field_6aa0088362f9a'),
(39702, 1015, 'flexible_content_1_items_4_description', 'Children should have their first dental visit when their first tooth appears or by their first birthday, followed by regular dental visits as recommended by their dentist.'),
(39703, 1015, '_flexible_content_1_items_4_description', 'field_6aa008bf62f9b'),
