(39857, 1015, '_flexible_content_2_heading', 'field_6aa00910843b2_field_68459c931bfb6'),
(39858, 1015, 'flexible_content_2_subheading_tag', 'h2'),
(39859, 1015, '_flexible_content_2_subheading_tag', 'field_6aa00910843b2_field_6944fae8b2df1'),
(39860, 1015, 'flexible_content_2_subheading', 'This will be FAQs description.'),
(39861, 1015, '_flexible_content_2_subheading', 'field_6aa00910843b2_field_6944faebb2df2'),
(39862, 1015, 'flexible_content_2_items_0_heading', 'How often should I visit the dentist?'),
(39863, 1015, '_flexible_content_2_items_0_heading', 'field_6aa0088362f9a'),
(39864, 1015, 'flexible_content_2_items_0_description', 'For many people, a routine dental check-up every six months is a useful general guideline. Your dentist may recommend a different schedule depending on your oral health and individual needs.'),
(39865, 1015, '_flexible_content_2_items_0_description', 'field_6aa008bf62f9b'),
(39866, 1015, 'flexible_content_2_items_1_heading', 'Is a root canal treatment painful?'),
(39867, 1015, '_flexible_content_2_items_1_heading', 'field_6aa0088362f9a'),
(39868, 1015, 'flexible_content_2_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(39869, 1015, '_flexible_content_2_items_1_description', 'field_6aa008bf62f9b'),
(39870, 1015, 'flexible_content_2_items_2_heading', 'What are dental implants?'),
(39871, 1015, '_flexible_content_2_items_2_heading', 'field_6aa0088362f9a'),
(39872, 1015, 'flexible_content_2_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(39873, 1015, '_flexible_content_2_items_2_description', 'field_6aa008bf62f9b'),
(39874, 1015, 'flexible_content_2_items_3_heading', 'How can I improve my oral health?'),
(39875, 1015, '_flexible_content_2_items_3_heading', 'field_6aa0088362f9a'),
(39876, 1015, 'flexible_content_2_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(39877, 1015, '_flexible_content_2_items_3_description', 'field_6aa008bf62f9b'),
(39878, 1015, 'flexible_content_2_items_4_heading', 'When should children first visit a dentist?'),
(39879, 1015, '_flexible_content_2_items_4_heading', 'field_6aa0088362f9a'),
(39880, 1015, 'flexible_content_2_items_4_description', 'Children should have their first dental visit when their first tooth appears or by their first birthday, followed by regular dental visits as recommended by their dentist.'),
(39881, 1015, '_flexible_content_2_items_4_description', 'field_6aa008bf62f9b'),
(39882, 1015, 'flexible_content_2_items', '5'),
