(40416, 1016, 'flexible_content_2_heading', 'FAQs Heading Here'),
(40417, 1016, '_flexible_content_2_heading', 'field_6aa00910843b2_field_68459c931bfb6'),
(40418, 1016, 'flexible_content_2_subheading_tag', 'h2'),
(40419, 1016, '_flexible_content_2_subheading_tag', 'field_6aa00910843b2_field_6944fae8b2df1'),
(40420, 1016, 'flexible_content_2_subheading', 'This will be FAQs description.'),
(40421, 1016, '_flexible_content_2_subheading', 'field_6aa00910843b2_field_6944faebb2df2'),
(40422, 1016, 'flexible_content_2_items_0_heading', 'How often should I visit the dentist?'),
(40423, 1016, '_flexible_content_2_items_0_heading', 'field_6aa0088362f9a'),
(40424, 1016, 'flexible_content_2_items_0_description', 'For many people, a routine dental check-up every six months is a useful general guideline. Your dentist may recommend a different schedule depending on your oral health and individual needs.'),
(40425, 1016, '_flexible_content_2_items_0_description', 'field_6aa008bf62f9b'),
(40426, 1016, 'flexible_content_2_items_1_heading', 'Is a root canal treatment painful?'),
(40427, 1016, '_flexible_content_2_items_1_heading', 'field_6aa0088362f9a'),
(40428, 1016, 'flexible_content_2_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(40429, 1016, '_flexible_content_2_items_1_description', 'field_6aa008bf62f9b'),
(40430, 1016, 'flexible_content_2_items_2_heading', 'What are dental implants?'),
(40431, 1016, '_flexible_content_2_items_2_heading', 'field_6aa0088362f9a'),
(40432, 1016, 'flexible_content_2_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(40433, 1016, '_flexible_content_2_items_2_description', 'field_6aa008bf62f9b'),
(40434, 1016, 'flexible_content_2_items_3_heading', 'How can I improve my oral health?'),
(40435, 1016, '_flexible_content_2_items_3_heading', 'field_6aa0088362f9a'),
(40436, 1016, 'flexible_content_2_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(40437, 1016, '_flexible_content_2_items_3_description', 'field_6aa008bf62f9b'),
(40438, 1016, 'flexible_content_2_items_4_heading', 'When should children first visit a dentist?'),
(40439, 1016, '_flexible_content_2_items_4_heading', 'field_6aa0088362f9a'),
(40440, 1016, 'flexible_content_2_items_4_description', 'Children should have their first dental visit when their first tooth appears or by their first birthday, followed by regular dental visits as recommended by their dentist.'),
(40441, 1016, '_flexible_content_2_items_4_description', 'field_6aa008bf62f9b'),
(40442, 1016, 'flexible_content_2_items', '5'),
(40443, 1016, '_flexible_content_2_items', 'field_6aa0088362f98'),
