(40797, 1017, '_flexible_content_1_heading_tag', 'field_6aa00910843b2_field_68459c3a1bfb5'),
(40798, 1017, 'flexible_content_1_heading', 'FAQs Heading Here'),
(40799, 1017, '_flexible_content_1_heading', 'field_6aa00910843b2_field_68459c931bfb6'),
(40800, 1017, 'flexible_content_1_subheading_tag', 'h2'),
(40801, 1017, '_flexible_content_1_subheading_tag', 'field_6aa00910843b2_field_6944fae8b2df1'),
(40802, 1017, 'flexible_content_1_subheading', 'This will be FAQs description.'),
(40803, 1017, '_flexible_content_1_subheading', 'field_6aa00910843b2_field_6944faebb2df2'),
(40804, 1017, 'flexible_content_1_items_0_heading', 'How often should I visit the dentist?'),
(40805, 1017, '_flexible_content_1_items_0_heading', 'field_6aa0088362f9a'),
(40806, 1017, 'flexible_content_1_items_0_description', 'For many people, a routine dental check-up every six months is a useful general guideline. Your dentist may recommend a different schedule depending on your oral health and individual needs.'),
(40807, 1017, '_flexible_content_1_items_0_description', 'field_6aa008bf62f9b'),
(40808, 1017, 'flexible_content_1_items_1_heading', 'Is a root canal treatment painful?'),
(40809, 1017, '_flexible_content_1_items_1_heading', 'field_6aa0088362f9a'),
(40810, 1017, 'flexible_content_1_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(40811, 1017, '_flexible_content_1_items_1_description', 'field_6aa008bf62f9b'),
(40812, 1017, 'flexible_content_1_items_2_heading', 'What are dental implants?'),
(40813, 1017, '_flexible_content_1_items_2_heading', 'field_6aa0088362f9a'),
(40814, 1017, 'flexible_content_1_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(40815, 1017, '_flexible_content_1_items_2_description', 'field_6aa008bf62f9b'),
(40816, 1017, 'flexible_content_1_items_3_heading', 'How can I improve my oral health?'),
(40817, 1017, '_flexible_content_1_items_3_heading', 'field_6aa0088362f9a'),
(40818, 1017, 'flexible_content_1_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(40819, 1017, '_flexible_content_1_items_3_description', 'field_6aa008bf62f9b'),
(40820, 1017, 'flexible_content_1_items_4_heading', 'When should children first visit a dentist?'),
(40821, 1017, '_flexible_content_1_items_4_heading', 'field_6aa0088362f9a'),
(40822, 1017, 'flexible_content_1_items_4_description', 'Children should have their first dental visit when their first tooth appears or by their first birthday, followed by regular dental visits as recommended by their dentist.'),
(40823, 1017, '_flexible_content_1_items_4_description', 'field_6aa008bf62f9b'),
(40824, 1017, 'flexible_content_1_items', '5'),
