INSERT INTO `wp_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(40978, 1017, 'flexible_content_2_subheading_tag', 'h2'),
(40979, 1017, '_flexible_content_2_subheading_tag', 'field_6aa00910843b2_field_6944fae8b2df1'),
(40980, 1017, 'flexible_content_2_subheading', 'This will be FAQs description.'),
(40981, 1017, '_flexible_content_2_subheading', 'field_6aa00910843b2_field_6944faebb2df2'),
(40982, 1017, 'flexible_content_2_items_0_heading', 'How often should I visit the dentist?'),
(40983, 1017, '_flexible_content_2_items_0_heading', 'field_6aa0088362f9a'),
(40984, 1017, 'flexible_content_2_items_0_description', 'For many people, a routine dental check-up every six months is a useful general guideline. Your dentist may recommend a different schedule depending on your oral health and individual needs.'),
(40985, 1017, '_flexible_content_2_items_0_description', 'field_6aa008bf62f9b'),
(40986, 1017, 'flexible_content_2_items_1_heading', 'Is a root canal treatment painful?'),
(40987, 1017, '_flexible_content_2_items_1_heading', 'field_6aa0088362f9a'),
(40988, 1017, 'flexible_content_2_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(40989, 1017, '_flexible_content_2_items_1_description', 'field_6aa008bf62f9b'),
(40990, 1017, 'flexible_content_2_items_2_heading', 'What are dental implants?'),
(40991, 1017, '_flexible_content_2_items_2_heading', 'field_6aa0088362f9a'),
(40992, 1017, 'flexible_content_2_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(40993, 1017, '_flexible_content_2_items_2_description', 'field_6aa008bf62f9b'),
(40994, 1017, 'flexible_content_2_items_3_heading', 'How can I improve my oral health?'),
(40995, 1017, '_flexible_content_2_items_3_heading', 'field_6aa0088362f9a'),
(40996, 1017, 'flexible_content_2_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(40997, 1017, '_flexible_content_2_items_3_description', 'field_6aa008bf62f9b'),
(40998, 1017, 'flexible_content_2_items_4_heading', 'When should children first visit a dentist?'),
(40999, 1017, '_flexible_content_2_items_4_heading', 'field_6aa0088362f9a'),
(41000, 1017, 'flexible_content_2_items_4_description', 'Children should have their first dental visit when their first tooth appears or by their first birthday, followed by regular dental visits as recommended by their dentist.'),
(41001, 1017, '_flexible_content_2_items_4_description', 'field_6aa008bf62f9b'),
(41002, 1017, 'flexible_content_2_items', '5'),
(41003, 1017, '_flexible_content_2_items', 'field_6aa0088362f98'),
