(41369, 1018, '_flexible_content_1_items_0_description', 'field_6aa008bf62f9b'),
(41370, 1018, 'flexible_content_1_items_1_heading', 'Is a root canal treatment painful?'),
(41371, 1018, '_flexible_content_1_items_1_heading', 'field_6aa0088362f9a'),
(41372, 1018, 'flexible_content_1_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(41373, 1018, '_flexible_content_1_items_1_description', 'field_6aa008bf62f9b'),
(41374, 1018, 'flexible_content_1_items_2_heading', 'What are dental implants?'),
(41375, 1018, '_flexible_content_1_items_2_heading', 'field_6aa0088362f9a'),
(41376, 1018, 'flexible_content_1_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(41377, 1018, '_flexible_content_1_items_2_description', 'field_6aa008bf62f9b'),
(41378, 1018, 'flexible_content_1_items_3_heading', 'How can I improve my oral health?'),
(41379, 1018, '_flexible_content_1_items_3_heading', 'field_6aa0088362f9a'),
(41380, 1018, 'flexible_content_1_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(41381, 1018, '_flexible_content_1_items_3_description', 'field_6aa008bf62f9b'),
(41382, 1018, 'flexible_content_1_items_4_heading', 'When should children first visit a dentist?'),
(41383, 1018, '_flexible_content_1_items_4_heading', 'field_6aa0088362f9a'),
(41384, 1018, 'flexible_content_1_items_4_description', 'Children should have their first dental visit when their first tooth appears or by their first birthday, followed by regular dental visits as recommended by their dentist.'),
(41385, 1018, '_flexible_content_1_items_4_description', 'field_6aa008bf62f9b'),
