(41537, 1018, '_flexible_content_2_heading_tag', 'field_6aa00910843b2_field_68459c3a1bfb5'),
(41538, 1018, 'flexible_content_2_heading', 'FAQs Heading Here'),
(41539, 1018, '_flexible_content_2_heading', 'field_6aa00910843b2_field_68459c931bfb6'),
(41540, 1018, 'flexible_content_2_subheading_tag', 'h2'),
(41541, 1018, '_flexible_content_2_subheading_tag', 'field_6aa00910843b2_field_6944fae8b2df1'),
(41542, 1018, 'flexible_content_2_subheading', 'This will be FAQs description.'),
(41543, 1018, '_flexible_content_2_subheading', 'field_6aa00910843b2_field_6944faebb2df2'),
(41544, 1018, 'flexible_content_2_items_0_heading', 'How often should I visit the dentist?'),
(41545, 1018, '_flexible_content_2_items_0_heading', 'field_6aa0088362f9a'),
(41546, 1018, 'flexible_content_2_items_0_description', 'For many people, a routine dental check-up every six months is a useful general guideline. Your dentist may recommend a different schedule depending on your oral health and individual needs.'),
(41547, 1018, '_flexible_content_2_items_0_description', 'field_6aa008bf62f9b'),
(41548, 1018, 'flexible_content_2_items_1_heading', 'Is a root canal treatment painful?'),
(41549, 1018, '_flexible_content_2_items_1_heading', 'field_6aa0088362f9a'),
(41550, 1018, 'flexible_content_2_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(41551, 1018, '_flexible_content_2_items_1_description', 'field_6aa008bf62f9b'),
(41552, 1018, 'flexible_content_2_items_2_heading', 'What are dental implants?'),
(41553, 1018, '_flexible_content_2_items_2_heading', 'field_6aa0088362f9a'),
(41554, 1018, 'flexible_content_2_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(41555, 1018, '_flexible_content_2_items_2_description', 'field_6aa008bf62f9b'),
(41556, 1018, 'flexible_content_2_items_3_heading', 'How can I improve my oral health?'),
(41557, 1018, '_flexible_content_2_items_3_heading', 'field_6aa0088362f9a'),
(41558, 1018, 'flexible_content_2_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(41559, 1018, '_flexible_content_2_items_3_description', 'field_6aa008bf62f9b'),
(41560, 1018, 'flexible_content_2_items_4_heading', 'When should children first visit a dentist?'),
(41561, 1018, '_flexible_content_2_items_4_heading', 'field_6aa0088362f9a'),
(41562, 1018, 'flexible_content_2_items_4_description', 'Children should have their first dental visit when their first tooth appears or by their first birthday, followed by regular dental visits as recommended by their dentist.'),
(41563, 1018, '_flexible_content_2_items_4_description', 'field_6aa008bf62f9b'),
(41564, 1018, 'flexible_content_2_items', '5'),
(41565, 1018, '_flexible_content_2_items', 'field_6aa0088362f98'),
