(41921, 1019, '_flexible_content_1_heading_tag', 'field_6aa00910843b2_field_68459c3a1bfb5'),
(41922, 1019, 'flexible_content_1_heading', 'FAQs Heading Here'),
(41923, 1019, '_flexible_content_1_heading', 'field_6aa00910843b2_field_68459c931bfb6'),
(41924, 1019, 'flexible_content_1_subheading_tag', 'h2'),
(41925, 1019, '_flexible_content_1_subheading_tag', 'field_6aa00910843b2_field_6944fae8b2df1'),
(41926, 1019, 'flexible_content_1_subheading', 'This will be FAQs description.'),
(41927, 1019, '_flexible_content_1_subheading', 'field_6aa00910843b2_field_6944faebb2df2'),
(41928, 1019, 'flexible_content_1_items_0_heading', 'How often should I visit the dentist?'),
(41929, 1019, '_flexible_content_1_items_0_heading', 'field_6aa0088362f9a'),
(41930, 1019, 'flexible_content_1_items_0_description', 'For many people, a routine dental check-up every six months is a useful general guideline. Your dentist may recommend a different schedule depending on your oral health and individual needs.'),
(41931, 1019, '_flexible_content_1_items_0_description', 'field_6aa008bf62f9b'),
(41932, 1019, 'flexible_content_1_items_1_heading', 'Is a root canal treatment painful?'),
(41933, 1019, '_flexible_content_1_items_1_heading', 'field_6aa0088362f9a'),
(41934, 1019, 'flexible_content_1_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(41935, 1019, '_flexible_content_1_items_1_description', 'field_6aa008bf62f9b'),
(41936, 1019, 'flexible_content_1_items_2_heading', 'What are dental implants?'),
(41937, 1019, '_flexible_content_1_items_2_heading', 'field_6aa0088362f9a'),
(41938, 1019, 'flexible_content_1_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(41939, 1019, '_flexible_content_1_items_2_description', 'field_6aa008bf62f9b'),
(41940, 1019, 'flexible_content_1_items_3_heading', 'How can I improve my oral health?'),
(41941, 1019, '_flexible_content_1_items_3_heading', 'field_6aa0088362f9a'),
(41942, 1019, 'flexible_content_1_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(41943, 1019, '_flexible_content_1_items_3_description', 'field_6aa008bf62f9b'),
(41944, 1019, 'flexible_content_1_items_4_heading', 'When should children first visit a dentist?'),
(41945, 1019, '_flexible_content_1_items_4_heading', 'field_6aa0088362f9a'),
(41946, 1019, 'flexible_content_1_items_4_description', 'Children should have their first dental visit when their first tooth appears or by their first birthday, followed by regular dental visits as recommended by their dentist.'),
(41947, 1019, '_flexible_content_1_items_4_description', 'field_6aa008bf62f9b'),
