(42103, 1019, '_flexible_content_2_subheading_tag', 'field_6aa00910843b2_field_6944fae8b2df1'),
(42104, 1019, 'flexible_content_2_subheading', 'This will be FAQs description.'),
(42105, 1019, '_flexible_content_2_subheading', 'field_6aa00910843b2_field_6944faebb2df2'),
(42106, 1019, 'flexible_content_2_items_0_heading', 'How often should I visit the dentist?'),
(42107, 1019, '_flexible_content_2_items_0_heading', 'field_6aa0088362f9a'),
(42108, 1019, 'flexible_content_2_items_0_description', 'For many people, a routine dental check-up every six months is a useful general guideline. Your dentist may recommend a different schedule depending on your oral health and individual needs.'),
(42109, 1019, '_flexible_content_2_items_0_description', 'field_6aa008bf62f9b'),
(42110, 1019, 'flexible_content_2_items_1_heading', 'Is a root canal treatment painful?'),
(42111, 1019, '_flexible_content_2_items_1_heading', 'field_6aa0088362f9a'),
(42112, 1019, 'flexible_content_2_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(42113, 1019, '_flexible_content_2_items_1_description', 'field_6aa008bf62f9b'),
(42114, 1019, 'flexible_content_2_items_2_heading', 'What are dental implants?'),
(42115, 1019, '_flexible_content_2_items_2_heading', 'field_6aa0088362f9a'),
(42116, 1019, 'flexible_content_2_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(42117, 1019, '_flexible_content_2_items_2_description', 'field_6aa008bf62f9b'),
(42118, 1019, 'flexible_content_2_items_3_heading', 'How can I improve my oral health?'),
(42119, 1019, '_flexible_content_2_items_3_heading', 'field_6aa0088362f9a'),
(42120, 1019, 'flexible_content_2_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(42121, 1019, '_flexible_content_2_items_3_description', 'field_6aa008bf62f9b'),
(42122, 1019, 'flexible_content_2_items_4_heading', 'When should children first visit a dentist?'),
(42123, 1019, '_flexible_content_2_items_4_heading', 'field_6aa0088362f9a'),
(42124, 1019, 'flexible_content_2_items_4_description', 'Children should have their first dental visit when their first tooth appears or by their first birthday, followed by regular dental visits as recommended by their dentist.'),
(42125, 1019, '_flexible_content_2_items_4_description', 'field_6aa008bf62f9b'),
(42126, 1019, 'flexible_content_2_items', '5'),
