(44654, 1042, '_flexible_content_2_items_1_description', 'field_6aa008bf62f9b'),
(44655, 1042, 'flexible_content_2_items_2_heading', 'What are dental implants?'),
(44656, 1042, '_flexible_content_2_items_2_heading', 'field_6aa0088362f9a'),
