(45331, 1043, 'flexible_content_1_heading', 'FAQs Heading Here'),
(45332, 1043, '_flexible_content_1_heading', 'field_6aa00910843b2_field_68459c931bfb6'),
(45333, 1043, 'flexible_content_1_subheading_tag', 'h2'),
(45334, 1043, '_flexible_content_1_subheading_tag', 'field_6aa00910843b2_field_6944fae8b2df1'),
(45335, 1043, 'flexible_content_1_subheading', 'This will be FAQs description.'),
(45336, 1043, '_flexible_content_1_subheading', 'field_6aa00910843b2_field_6944faebb2df2'),
(45337, 1043, 'flexible_content_1_items_0_heading', 'How often should I visit the dentist?'),
(45338, 1043, '_flexible_content_1_items_0_heading', 'field_6aa0088362f9a'),
(45339, 1043, 'flexible_content_1_items_0_description', 'For many people, a routine dental check-up every six months is a useful general guideline. Your dentist may recommend a different schedule depending on your oral health and individual needs.'),
(45340, 1043, '_flexible_content_1_items_0_description', 'field_6aa008bf62f9b'),
(45341, 1043, 'flexible_content_1_items_1_heading', 'Is a root canal treatment painful?'),
(45342, 1043, '_flexible_content_1_items_1_heading', 'field_6aa0088362f9a'),
(45343, 1043, 'flexible_content_1_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(45344, 1043, '_flexible_content_1_items_1_description', 'field_6aa008bf62f9b'),
(45345, 1043, 'flexible_content_1_items_2_heading', 'What are dental implants?'),
(45346, 1043, '_flexible_content_1_items_2_heading', 'field_6aa0088362f9a'),
(45347, 1043, 'flexible_content_1_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(45348, 1043, '_flexible_content_1_items_2_description', 'field_6aa008bf62f9b'),
(45349, 1043, 'flexible_content_1_items_3_heading', 'How can I improve my oral health?'),
(45350, 1043, '_flexible_content_1_items_3_heading', 'field_6aa0088362f9a'),
(45351, 1043, 'flexible_content_1_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(45352, 1043, '_flexible_content_1_items_3_description', 'field_6aa008bf62f9b'),
(45353, 1043, 'flexible_content_1_items_4_heading', 'When should children first visit a dentist?'),
(45354, 1043, '_flexible_content_1_items_4_heading', 'field_6aa0088362f9a'),
(45355, 1043, 'flexible_content_1_items_4_description', 'Children should have their first dental visit when their first tooth appears or by their first birthday, followed by regular dental visits as recommended by their dentist.'),
(45356, 1043, '_flexible_content_1_items_4_description', 'field_6aa008bf62f9b'),
(45357, 1043, 'flexible_content_1_items', '5'),
