(46080, 1044, '_flexible_content_1_heading_tag', 'field_6aa00910843b2_field_68459c3a1bfb5'),
(46081, 1044, 'flexible_content_1_heading', 'FAQs Heading Here'),
(46082, 1044, '_flexible_content_1_heading', 'field_6aa00910843b2_field_68459c931bfb6'),
(46083, 1044, 'flexible_content_1_subheading_tag', 'h2'),
(46084, 1044, '_flexible_content_1_subheading_tag', 'field_6aa00910843b2_field_6944fae8b2df1'),
(46085, 1044, 'flexible_content_1_subheading', 'This will be FAQs description.'),
(46086, 1044, '_flexible_content_1_subheading', 'field_6aa00910843b2_field_6944faebb2df2'),
(46087, 1044, 'flexible_content_1_items_0_heading', 'How often should I visit the dentist?'),
(46088, 1044, '_flexible_content_1_items_0_heading', 'field_6aa0088362f9a'),
(46089, 1044, 'flexible_content_1_items_0_description', 'For many people, a routine dental check-up every six months is a useful general guideline. Your dentist may recommend a different schedule depending on your oral health and individual needs.'),
(46090, 1044, '_flexible_content_1_items_0_description', 'field_6aa008bf62f9b'),
(46091, 1044, 'flexible_content_1_items_1_heading', 'Is a root canal treatment painful?'),
(46092, 1044, '_flexible_content_1_items_1_heading', 'field_6aa0088362f9a'),
(46093, 1044, 'flexible_content_1_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(46094, 1044, '_flexible_content_1_items_1_description', 'field_6aa008bf62f9b'),
(46095, 1044, 'flexible_content_1_items_2_heading', 'What are dental implants?'),
(46096, 1044, '_flexible_content_1_items_2_heading', 'field_6aa0088362f9a'),
(46097, 1044, 'flexible_content_1_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(46098, 1044, '_flexible_content_1_items_2_description', 'field_6aa008bf62f9b'),
(46099, 1044, 'flexible_content_1_items_3_heading', 'How can I improve my oral health?'),
(46100, 1044, '_flexible_content_1_items_3_heading', 'field_6aa0088362f9a'),
(46101, 1044, 'flexible_content_1_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(46102, 1044, '_flexible_content_1_items_3_description', 'field_6aa008bf62f9b'),
(46103, 1044, 'flexible_content_1_items_4_heading', 'When should children first visit a dentist?'),
(46104, 1044, '_flexible_content_1_items_4_heading', 'field_6aa0088362f9a'),
(46105, 1044, 'flexible_content_1_items_4_description', 'Children should have their first dental visit when their first tooth appears or by their first birthday, followed by regular dental visits as recommended by their dentist.'),
(46106, 1044, '_flexible_content_1_items_4_description', 'field_6aa008bf62f9b'),
(46107, 1044, 'flexible_content_1_items', '5'),
