(46145, 1044, 'flexible_content_2_subheading', 'This will be FAQs description.'),
(46146, 1044, '_flexible_content_2_subheading', 'field_6aa00910843b2_field_6944faebb2df2'),
(46147, 1044, 'flexible_content_2_items_0_heading', 'How often should I visit the dentist?'),
(46148, 1044, '_flexible_content_2_items_0_heading', 'field_6aa0088362f9a'),
(46149, 1044, 'flexible_content_2_items_0_description', 'For many people, a routine dental check-up every six months is a useful general guideline. Your dentist may recommend a different schedule depending on your oral health and individual needs.'),
(46150, 1044, '_flexible_content_2_items_0_description', 'field_6aa008bf62f9b'),
(46151, 1044, 'flexible_content_2_items_1_heading', 'Is a root canal treatment painful?'),
(46152, 1044, '_flexible_content_2_items_1_heading', 'field_6aa0088362f9a'),
(46153, 1044, 'flexible_content_2_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(46154, 1044, '_flexible_content_2_items_1_description', 'field_6aa008bf62f9b'),
(46155, 1044, 'flexible_content_2_items_2_heading', 'What are dental implants?'),
(46156, 1044, '_flexible_content_2_items_2_heading', 'field_6aa0088362f9a'),
(46157, 1044, 'flexible_content_2_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(46158, 1044, '_flexible_content_2_items_2_description', 'field_6aa008bf62f9b'),
(46159, 1044, 'flexible_content_2_items_3_heading', 'How can I improve my oral health?'),
(46160, 1044, '_flexible_content_2_items_3_heading', 'field_6aa0088362f9a'),
(46161, 1044, 'flexible_content_2_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(46162, 1044, '_flexible_content_2_items_3_description', 'field_6aa008bf62f9b'),
(46163, 1044, 'flexible_content_2_items_4_heading', 'When should children first visit a dentist?'),
