(47654, 1046, '_flexible_content_2_items_1_description', 'field_6aa008bf62f9b'),
(47655, 1046, 'flexible_content_2_items_2_heading', 'What are dental implants?'),
(47656, 1046, '_flexible_content_2_items_2_heading', 'field_6aa0088362f9a'),
(47657, 1046, 'flexible_content_2_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(47658, 1046, '_flexible_content_2_items_2_description', 'field_6aa008bf62f9b'),
(47659, 1046, 'flexible_content_2_items_3_heading', 'How can I improve my oral health?'),
(47660, 1046, '_flexible_content_2_items_3_heading', 'field_6aa0088362f9a'),
(47661, 1046, 'flexible_content_2_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(47662, 1046, '_flexible_content_2_items_3_description', 'field_6aa008bf62f9b'),
(47663, 1046, 'flexible_content_2_items_4_heading', 'When should children first visit a dentist?'),
(47664, 1046, '_flexible_content_2_items_4_heading', 'field_6aa0088362f9a'),
(47665, 1046, 'flexible_content_2_items_4_description', 'Children should have their first dental visit when their first tooth appears or by their first birthday, followed by regular dental visits as recommended by their dentist.'),
(47666, 1046, '_flexible_content_2_items_4_description', 'field_6aa008bf62f9b'),
