(48331, 1047, 'flexible_content_1_heading', 'FAQs Heading Here'),
(48332, 1047, '_flexible_content_1_heading', 'field_6aa00910843b2_field_68459c931bfb6'),
(48333, 1047, 'flexible_content_1_subheading_tag', 'h2'),
(48334, 1047, '_flexible_content_1_subheading_tag', 'field_6aa00910843b2_field_6944fae8b2df1'),
(48335, 1047, 'flexible_content_1_subheading', 'This will be FAQs description.'),
(48336, 1047, '_flexible_content_1_subheading', 'field_6aa00910843b2_field_6944faebb2df2'),
(48337, 1047, 'flexible_content_1_items_0_heading', 'How often should I visit the dentist?'),
(48338, 1047, '_flexible_content_1_items_0_heading', 'field_6aa0088362f9a'),
(48339, 1047, 'flexible_content_1_items_0_description', 'For many people, a routine dental check-up every six months is a useful general guideline. Your dentist may recommend a different schedule depending on your oral health and individual needs.'),
(48340, 1047, '_flexible_content_1_items_0_description', 'field_6aa008bf62f9b'),
(48341, 1047, 'flexible_content_1_items_1_heading', 'Is a root canal treatment painful?'),
(48342, 1047, '_flexible_content_1_items_1_heading', 'field_6aa0088362f9a'),
(48343, 1047, 'flexible_content_1_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(48344, 1047, '_flexible_content_1_items_1_description', 'field_6aa008bf62f9b'),
(48345, 1047, 'flexible_content_1_items_2_heading', 'What are dental implants?'),
(48346, 1047, '_flexible_content_1_items_2_heading', 'field_6aa0088362f9a'),
(48347, 1047, 'flexible_content_1_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(48348, 1047, '_flexible_content_1_items_2_description', 'field_6aa008bf62f9b'),
(48349, 1047, 'flexible_content_1_items_3_heading', 'How can I improve my oral health?'),
(48350, 1047, '_flexible_content_1_items_3_heading', 'field_6aa0088362f9a'),
(48351, 1047, 'flexible_content_1_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(48352, 1047, '_flexible_content_1_items_3_description', 'field_6aa008bf62f9b'),
(48353, 1047, 'flexible_content_1_items_4_heading', 'When should children first visit a dentist?'),
(48354, 1047, '_flexible_content_1_items_4_heading', 'field_6aa0088362f9a');
INSERT INTO `wp_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(48355, 1047, 'flexible_content_1_items_4_description', 'Children should have their first dental visit when their first tooth appears or by their first birthday, followed by regular dental visits as recommended by their dentist.'),
(48356, 1047, '_flexible_content_1_items_4_description', 'field_6aa008bf62f9b'),
