(48390, 1047, '_flexible_content_2_heading_tag', 'field_6aa00910843b2_field_68459c3a1bfb5'),
(48391, 1047, 'flexible_content_2_heading', 'FAQs Heading Here'),
(48392, 1047, '_flexible_content_2_heading', 'field_6aa00910843b2_field_68459c931bfb6'),
(48393, 1047, 'flexible_content_2_subheading_tag', 'h2'),
(48394, 1047, '_flexible_content_2_subheading_tag', 'field_6aa00910843b2_field_6944fae8b2df1'),
(48395, 1047, 'flexible_content_2_subheading', 'This will be FAQs description.'),
(48396, 1047, '_flexible_content_2_subheading', 'field_6aa00910843b2_field_6944faebb2df2'),
(48397, 1047, 'flexible_content_2_items_0_heading', 'How often should I visit the dentist?'),
(48398, 1047, '_flexible_content_2_items_0_heading', 'field_6aa0088362f9a'),
(48399, 1047, 'flexible_content_2_items_0_description', 'For many people, a routine dental check-up every six months is a useful general guideline. Your dentist may recommend a different schedule depending on your oral health and individual needs.'),
(48400, 1047, '_flexible_content_2_items_0_description', 'field_6aa008bf62f9b'),
(48401, 1047, 'flexible_content_2_items_1_heading', 'Is a root canal treatment painful?'),
(48402, 1047, '_flexible_content_2_items_1_heading', 'field_6aa0088362f9a'),
(48403, 1047, 'flexible_content_2_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(48404, 1047, '_flexible_content_2_items_1_description', 'field_6aa008bf62f9b'),
(48405, 1047, 'flexible_content_2_items_2_heading', 'What are dental implants?'),
(48406, 1047, '_flexible_content_2_items_2_heading', 'field_6aa0088362f9a'),
(48407, 1047, 'flexible_content_2_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(48408, 1047, '_flexible_content_2_items_2_description', 'field_6aa008bf62f9b'),
(48409, 1047, 'flexible_content_2_items_3_heading', 'How can I improve my oral health?'),
(48410, 1047, '_flexible_content_2_items_3_heading', 'field_6aa0088362f9a'),
(48411, 1047, 'flexible_content_2_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(48412, 1047, '_flexible_content_2_items_3_description', 'field_6aa008bf62f9b'),
(48413, 1047, 'flexible_content_2_items_4_heading', 'When should children first visit a dentist?'),
(48414, 1047, '_flexible_content_2_items_4_heading', 'field_6aa0088362f9a'),
(48415, 1047, 'flexible_content_2_items_4_description', 'Children should have their first dental visit when their first tooth appears or by their first birthday, followed by regular dental visits as recommended by their dentist.'),
(48416, 1047, '_flexible_content_2_items_4_description', 'field_6aa008bf62f9b'),
(48417, 1047, 'flexible_content_2_items', '5'),
