(49085, 1048, 'flexible_content_1_subheading', 'This will be FAQs description.'),
(49086, 1048, '_flexible_content_1_subheading', 'field_6aa00910843b2_field_6944faebb2df2'),
(49087, 1048, 'flexible_content_1_items_0_heading', 'How often should I visit the dentist?'),
(49088, 1048, '_flexible_content_1_items_0_heading', 'field_6aa0088362f9a'),
(49089, 1048, 'flexible_content_1_items_0_description', 'For many people, a routine dental check-up every six months is a useful general guideline. Your dentist may recommend a different schedule depending on your oral health and individual needs.'),
(49090, 1048, '_flexible_content_1_items_0_description', 'field_6aa008bf62f9b'),
(49091, 1048, 'flexible_content_1_items_1_heading', 'Is a root canal treatment painful?'),
(49092, 1048, '_flexible_content_1_items_1_heading', 'field_6aa0088362f9a'),
(49093, 1048, 'flexible_content_1_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(49094, 1048, '_flexible_content_1_items_1_description', 'field_6aa008bf62f9b'),
(49095, 1048, 'flexible_content_1_items_2_heading', 'What are dental implants?'),
(49096, 1048, '_flexible_content_1_items_2_heading', 'field_6aa0088362f9a'),
(49097, 1048, 'flexible_content_1_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(49098, 1048, '_flexible_content_1_items_2_description', 'field_6aa008bf62f9b'),
(49099, 1048, 'flexible_content_1_items_3_heading', 'How can I improve my oral health?'),
(49100, 1048, '_flexible_content_1_items_3_heading', 'field_6aa0088362f9a'),
(49101, 1048, 'flexible_content_1_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(49102, 1048, '_flexible_content_1_items_3_description', 'field_6aa008bf62f9b'),
(49103, 1048, 'flexible_content_1_items_4_heading', 'When should children first visit a dentist?'),
(49104, 1048, '_flexible_content_1_items_4_heading', 'field_6aa0088362f9a'),
(49105, 1048, 'flexible_content_1_items_4_description', 'Children should have their first dental visit when their first tooth appears or by their first birthday, followed by regular dental visits as recommended by their dentist.'),
(49106, 1048, '_flexible_content_1_items_4_description', 'field_6aa008bf62f9b'),
