(49144, 1048, '_flexible_content_2_subheading_tag', 'field_6aa00910843b2_field_6944fae8b2df1'),
(49145, 1048, 'flexible_content_2_subheading', 'This will be FAQs description.'),
(49146, 1048, '_flexible_content_2_subheading', 'field_6aa00910843b2_field_6944faebb2df2'),
(49147, 1048, 'flexible_content_2_items_0_heading', 'How often should I visit the dentist?'),
(49148, 1048, '_flexible_content_2_items_0_heading', 'field_6aa0088362f9a'),
(49149, 1048, 'flexible_content_2_items_0_description', 'For many people, a routine dental check-up every six months is a useful general guideline. Your dentist may recommend a different schedule depending on your oral health and individual needs.'),
(49150, 1048, '_flexible_content_2_items_0_description', 'field_6aa008bf62f9b'),
(49151, 1048, 'flexible_content_2_items_1_heading', 'Is a root canal treatment painful?'),
(49152, 1048, '_flexible_content_2_items_1_heading', 'field_6aa0088362f9a'),
(49153, 1048, 'flexible_content_2_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(49154, 1048, '_flexible_content_2_items_1_description', 'field_6aa008bf62f9b'),
(49155, 1048, 'flexible_content_2_items_2_heading', 'What are dental implants?'),
