(50585, 1051, 'flexible_content_1_heading', 'FAQs Heading Here'),
(50586, 1051, '_flexible_content_1_heading', 'field_6aa00910843b2_field_68459c931bfb6'),
(50587, 1051, 'flexible_content_1_subheading_tag', 'h3'),
(50588, 1051, '_flexible_content_1_subheading_tag', 'field_6aa00910843b2_field_6944fae8b2df1'),
(50589, 1051, 'flexible_content_1_subheading', 'This will be FAQs description.'),
(50590, 1051, '_flexible_content_1_subheading', 'field_6aa00910843b2_field_6944faebb2df2'),
(50591, 1051, 'flexible_content_1_items_0_heading', 'How often should I visit the dentist?'),
(50592, 1051, '_flexible_content_1_items_0_heading', 'field_6aa0088362f9a'),
(50593, 1051, 'flexible_content_1_items_0_description', 'For many people, a routine dental check-up every six months is a useful general guideline. Your dentist may recommend a different schedule depending on your oral health and individual needs.'),
(50594, 1051, '_flexible_content_1_items_0_description', 'field_6aa008bf62f9b'),
(50595, 1051, 'flexible_content_1_items_1_heading', 'Is a root canal treatment painful?'),
(50596, 1051, '_flexible_content_1_items_1_heading', 'field_6aa0088362f9a'),
(50597, 1051, 'flexible_content_1_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(50598, 1051, '_flexible_content_1_items_1_description', 'field_6aa008bf62f9b'),
(50599, 1051, 'flexible_content_1_items_2_heading', 'What are dental implants?'),
(50600, 1051, '_flexible_content_1_items_2_heading', 'field_6aa0088362f9a'),
(50601, 1051, 'flexible_content_1_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(50602, 1051, '_flexible_content_1_items_2_description', 'field_6aa008bf62f9b'),
(50603, 1051, 'flexible_content_1_items_3_heading', 'How can I improve my oral health?'),
(50604, 1051, '_flexible_content_1_items_3_heading', 'field_6aa0088362f9a'),
(50605, 1051, 'flexible_content_1_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(50606, 1051, '_flexible_content_1_items_3_description', 'field_6aa008bf62f9b'),
(50607, 1051, 'flexible_content_1_items_4_heading', 'When should children first visit a dentist?'),
(50608, 1051, '_flexible_content_1_items_4_heading', 'field_6aa0088362f9a'),
(50609, 1051, 'flexible_content_1_items_4_description', 'Children should have their first dental visit when their first tooth appears or by their first birthday, followed by regular dental visits as recommended by their dentist.'),
(50610, 1051, '_flexible_content_1_items_4_description', 'field_6aa008bf62f9b'),
