(51339, 1052, 'flexible_content_1_heading', 'FAQs Heading Here'),
(51340, 1052, '_flexible_content_1_heading', 'field_6aa00910843b2_field_68459c931bfb6'),
(51341, 1052, 'flexible_content_1_subheading_tag', 'h3'),
(51342, 1052, '_flexible_content_1_subheading_tag', 'field_6aa00910843b2_field_6944fae8b2df1'),
(51343, 1052, 'flexible_content_1_subheading', 'This will be FAQs description.'),
(51344, 1052, '_flexible_content_1_subheading', 'field_6aa00910843b2_field_6944faebb2df2'),
(51345, 1052, 'flexible_content_1_items_0_heading', 'How often should I visit the dentist?'),
(51346, 1052, '_flexible_content_1_items_0_heading', 'field_6aa0088362f9a'),
(51347, 1052, 'flexible_content_1_items_0_description', 'For many people, a routine dental check-up every six months is a useful general guideline. Your dentist may recommend a different schedule depending on your oral health and individual needs.'),
(51348, 1052, '_flexible_content_1_items_0_description', 'field_6aa008bf62f9b'),
(51349, 1052, 'flexible_content_1_items_1_heading', 'Is a root canal treatment painful?'),
(51350, 1052, '_flexible_content_1_items_1_heading', 'field_6aa0088362f9a'),
(51351, 1052, 'flexible_content_1_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(51352, 1052, '_flexible_content_1_items_1_description', 'field_6aa008bf62f9b'),
(51353, 1052, 'flexible_content_1_items_2_heading', 'What are dental implants?'),
(51354, 1052, '_flexible_content_1_items_2_heading', 'field_6aa0088362f9a'),
(51355, 1052, 'flexible_content_1_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(51356, 1052, '_flexible_content_1_items_2_description', 'field_6aa008bf62f9b'),
(51357, 1052, 'flexible_content_1_items_3_heading', 'How can I improve my oral health?'),
(51358, 1052, '_flexible_content_1_items_3_heading', 'field_6aa0088362f9a'),
(51359, 1052, 'flexible_content_1_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(51360, 1052, '_flexible_content_1_items_3_description', 'field_6aa008bf62f9b'),
(51361, 1052, 'flexible_content_1_items_4_heading', 'When should children first visit a dentist?'),
(51362, 1052, '_flexible_content_1_items_4_heading', 'field_6aa0088362f9a'),
(51363, 1052, 'flexible_content_1_items_4_description', 'Children should have their first dental visit when their first tooth appears or by their first birthday, followed by regular dental visits as recommended by their dentist.'),
(51364, 1052, '_flexible_content_1_items_4_description', 'field_6aa008bf62f9b'),
