(52094, 1054, '_flexible_content_1_heading_tag', 'field_6aa00910843b2_field_68459c3a1bfb5'),
(52095, 1054, 'flexible_content_1_heading', 'FAQs Heading Here'),
(52096, 1054, '_flexible_content_1_heading', 'field_6aa00910843b2_field_68459c931bfb6'),
(52097, 1054, 'flexible_content_1_subheading_tag', 'h3'),
(52098, 1054, '_flexible_content_1_subheading_tag', 'field_6aa00910843b2_field_6944fae8b2df1'),
(52099, 1054, 'flexible_content_1_subheading', 'This will be FAQs description.'),
(52100, 1054, '_flexible_content_1_subheading', 'field_6aa00910843b2_field_6944faebb2df2'),
(52101, 1054, 'flexible_content_1_items_0_heading', 'How often should I visit the dentist?'),
(52102, 1054, '_flexible_content_1_items_0_heading', 'field_6aa0088362f9a'),
(52103, 1054, 'flexible_content_1_items_0_description', 'For many people, a routine dental check-up every six months is a useful general guideline. Your dentist may recommend a different schedule depending on your oral health and individual needs.'),
(52104, 1054, '_flexible_content_1_items_0_description', 'field_6aa008bf62f9b'),
(52105, 1054, 'flexible_content_1_items_1_heading', 'Is a root canal treatment painful?'),
(52106, 1054, '_flexible_content_1_items_1_heading', 'field_6aa0088362f9a'),
(52107, 1054, 'flexible_content_1_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(52108, 1054, '_flexible_content_1_items_1_description', 'field_6aa008bf62f9b'),
(52109, 1054, 'flexible_content_1_items_2_heading', 'What are dental implants?'),
(52110, 1054, '_flexible_content_1_items_2_heading', 'field_6aa0088362f9a'),
(52111, 1054, 'flexible_content_1_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(52112, 1054, '_flexible_content_1_items_2_description', 'field_6aa008bf62f9b'),
(52113, 1054, 'flexible_content_1_items_3_heading', 'How can I improve my oral health?'),
(52114, 1054, '_flexible_content_1_items_3_heading', 'field_6aa0088362f9a'),
(52115, 1054, 'flexible_content_1_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(52116, 1054, '_flexible_content_1_items_3_description', 'field_6aa008bf62f9b'),
(52117, 1054, 'flexible_content_1_items_4_heading', 'When should children first visit a dentist?'),
(52118, 1054, '_flexible_content_1_items_4_heading', 'field_6aa0088362f9a'),
(52119, 1054, 'flexible_content_1_items_4_description', 'Children should have their first dental visit when their first tooth appears or by their first birthday, followed by regular dental visits as recommended by their dentist.'),
(52120, 1054, '_flexible_content_1_items_4_description', 'field_6aa008bf62f9b'),
(52121, 1054, 'flexible_content_1_items', '5'),
