(52171, 1054, 'flexible_content_2_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(52172, 1054, '_flexible_content_2_items_2_description', 'field_6aa008bf62f9b'),
(52173, 1054, 'flexible_content_2_items_3_heading', 'How can I improve my oral health?'),
(52174, 1054, '_flexible_content_2_items_3_heading', 'field_6aa0088362f9a'),
(52175, 1054, 'flexible_content_2_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(52176, 1054, '_flexible_content_2_items_3_description', 'field_6aa008bf62f9b'),
(52177, 1054, 'flexible_content_2_items_4_heading', 'When should children first visit a dentist?'),
(52178, 1054, '_flexible_content_2_items_4_heading', 'field_6aa0088362f9a'),
(52179, 1054, 'flexible_content_2_items_4_description', 'Children should have their first dental visit when their first tooth appears or by their first birthday, followed by regular dental visits as recommended by their dentist.'),
(52180, 1054, '_flexible_content_2_items_4_description', 'field_6aa008bf62f9b'),
