(52914, 1057, '_flexible_content_2_heading_tag', 'field_6aa00910843b2_field_68459c3a1bfb5'),
(52915, 1057, 'flexible_content_2_heading', 'FAQs Heading Here'),
(52916, 1057, '_flexible_content_2_heading', 'field_6aa00910843b2_field_68459c931bfb6'),
(52917, 1057, 'flexible_content_2_subheading_tag', 'h3'),
(52918, 1057, '_flexible_content_2_subheading_tag', 'field_6aa00910843b2_field_6944fae8b2df1'),
(52919, 1057, 'flexible_content_2_subheading', 'This will be FAQs description.'),
(52920, 1057, '_flexible_content_2_subheading', 'field_6aa00910843b2_field_6944faebb2df2'),
(52921, 1057, 'flexible_content_2_items_0_heading', 'How often should I visit the dentist?'),
(52922, 1057, '_flexible_content_2_items_0_heading', 'field_6aa0088362f9a'),
(52923, 1057, 'flexible_content_2_items_0_description', 'For many people, a routine dental check-up every six months is a useful general guideline. Your dentist may recommend a different schedule depending on your oral health and individual needs.'),
(52924, 1057, '_flexible_content_2_items_0_description', 'field_6aa008bf62f9b'),
(52925, 1057, 'flexible_content_2_items_1_heading', 'Is a root canal treatment painful?'),
(52926, 1057, '_flexible_content_2_items_1_heading', 'field_6aa0088362f9a'),
(52927, 1057, 'flexible_content_2_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(52928, 1057, '_flexible_content_2_items_1_description', 'field_6aa008bf62f9b'),
(52929, 1057, 'flexible_content_2_items_2_heading', 'What are dental implants?'),
(52930, 1057, '_flexible_content_2_items_2_heading', 'field_6aa0088362f9a'),
(52931, 1057, 'flexible_content_2_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(52932, 1057, '_flexible_content_2_items_2_description', 'field_6aa008bf62f9b'),
(52933, 1057, 'flexible_content_2_items_3_heading', 'How can I improve my oral health?'),
(52934, 1057, '_flexible_content_2_items_3_heading', 'field_6aa0088362f9a'),
(52935, 1057, 'flexible_content_2_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(52936, 1057, '_flexible_content_2_items_3_description', 'field_6aa008bf62f9b'),
(52937, 1057, 'flexible_content_2_items_4_heading', 'When should children first visit a dentist?'),
(52938, 1057, '_flexible_content_2_items_4_heading', 'field_6aa0088362f9a'),
(52939, 1057, 'flexible_content_2_items_4_description', 'Children should have their first dental visit when their first tooth appears or by their first birthday, followed by regular dental visits as recommended by their dentist.'),
(52940, 1057, '_flexible_content_2_items_4_description', 'field_6aa008bf62f9b'),
(52941, 1057, 'flexible_content_2_items', '5'),
