(54377, 1060, 'flexible_content_1_heading', 'FAQs Heading Here'),
(54378, 1060, '_flexible_content_1_heading', 'field_6aa00910843b2_field_68459c931bfb6'),
(54379, 1060, 'flexible_content_1_subheading_tag', 'h3'),
(54380, 1060, '_flexible_content_1_subheading_tag', 'field_6aa00910843b2_field_6944fae8b2df1'),
(54381, 1060, 'flexible_content_1_subheading', 'This will be FAQs description.'),
(54382, 1060, '_flexible_content_1_subheading', 'field_6aa00910843b2_field_6944faebb2df2'),
(54383, 1060, 'flexible_content_1_items_0_heading', 'How often should I visit the dentist?'),
(54384, 1060, '_flexible_content_1_items_0_heading', 'field_6aa0088362f9a'),
(54385, 1060, 'flexible_content_1_items_0_description', 'For many people, a routine dental check-up every six months is a useful general guideline. Your dentist may recommend a different schedule depending on your oral health and individual needs.'),
(54386, 1060, '_flexible_content_1_items_0_description', 'field_6aa008bf62f9b'),
(54387, 1060, 'flexible_content_1_items_1_heading', 'Is a root canal treatment painful?'),
(54388, 1060, '_flexible_content_1_items_1_heading', 'field_6aa0088362f9a'),
(54389, 1060, 'flexible_content_1_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(54390, 1060, '_flexible_content_1_items_1_description', 'field_6aa008bf62f9b'),
(54391, 1060, 'flexible_content_1_items_2_heading', 'What are dental implants?'),
(54392, 1060, '_flexible_content_1_items_2_heading', 'field_6aa0088362f9a'),
(54393, 1060, 'flexible_content_1_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(54394, 1060, '_flexible_content_1_items_2_description', 'field_6aa008bf62f9b'),
(54395, 1060, 'flexible_content_1_items_3_heading', 'How can I improve my oral health?'),
(54396, 1060, '_flexible_content_1_items_3_heading', 'field_6aa0088362f9a'),
(54397, 1060, 'flexible_content_1_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(54398, 1060, '_flexible_content_1_items_3_description', 'field_6aa008bf62f9b'),
(54399, 1060, 'flexible_content_1_items_4_heading', 'When should children first visit a dentist?'),
(54400, 1060, '_flexible_content_1_items_4_heading', 'field_6aa0088362f9a'),
(54401, 1060, 'flexible_content_1_items_4_description', 'Children should have their first dental visit when their first tooth appears or by their first birthday, followed by regular dental visits as recommended by their dentist.'),
(54402, 1060, '_flexible_content_1_items_4_description', 'field_6aa008bf62f9b'),
