(54446, 1060, '_flexible_content_2_items_0_description', 'field_6aa008bf62f9b'),
(54447, 1060, 'flexible_content_2_items_1_heading', 'Is a root canal treatment painful?'),
(54448, 1060, '_flexible_content_2_items_1_heading', 'field_6aa0088362f9a'),
(54449, 1060, 'flexible_content_2_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(54450, 1060, '_flexible_content_2_items_1_description', 'field_6aa008bf62f9b'),
(54451, 1060, 'flexible_content_2_items_2_heading', 'What are dental implants?'),
(54452, 1060, '_flexible_content_2_items_2_heading', 'field_6aa0088362f9a'),
