(55137, 1061, 'flexible_content_1_heading', 'FAQs Heading Here'),
(55138, 1061, '_flexible_content_1_heading', 'field_6aa00910843b2_field_68459c931bfb6'),
(55139, 1061, 'flexible_content_1_subheading_tag', 'h3'),
(55140, 1061, '_flexible_content_1_subheading_tag', 'field_6aa00910843b2_field_6944fae8b2df1'),
(55141, 1061, 'flexible_content_1_subheading', 'This will be FAQs description.'),
(55142, 1061, '_flexible_content_1_subheading', 'field_6aa00910843b2_field_6944faebb2df2'),
(55143, 1061, 'flexible_content_1_items_0_heading', 'How often should I visit the dentist?'),
(55144, 1061, '_flexible_content_1_items_0_heading', 'field_6aa0088362f9a'),
(55145, 1061, 'flexible_content_1_items_0_description', 'For many people, a routine dental check-up every six months is a useful general guideline. Your dentist may recommend a different schedule depending on your oral health and individual needs.'),
(55146, 1061, '_flexible_content_1_items_0_description', 'field_6aa008bf62f9b'),
(55147, 1061, 'flexible_content_1_items_1_heading', 'Is a root canal treatment painful?'),
(55148, 1061, '_flexible_content_1_items_1_heading', 'field_6aa0088362f9a'),
(55149, 1061, 'flexible_content_1_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(55150, 1061, '_flexible_content_1_items_1_description', 'field_6aa008bf62f9b'),
(55151, 1061, 'flexible_content_1_items_2_heading', 'What are dental implants?'),
(55152, 1061, '_flexible_content_1_items_2_heading', 'field_6aa0088362f9a'),
(55153, 1061, 'flexible_content_1_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(55154, 1061, '_flexible_content_1_items_2_description', 'field_6aa008bf62f9b'),
(55155, 1061, 'flexible_content_1_items_3_heading', 'How can I improve my oral health?'),
(55156, 1061, '_flexible_content_1_items_3_heading', 'field_6aa0088362f9a'),
(55157, 1061, 'flexible_content_1_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(55158, 1061, '_flexible_content_1_items_3_description', 'field_6aa008bf62f9b'),
(55159, 1061, 'flexible_content_1_items_4_heading', 'When should children first visit a dentist?'),
(55160, 1061, '_flexible_content_1_items_4_heading', 'field_6aa0088362f9a'),
(55161, 1061, 'flexible_content_1_items_4_description', 'Children should have their first dental visit when their first tooth appears or by their first birthday, followed by regular dental visits as recommended by their dentist.'),
(55162, 1061, '_flexible_content_1_items_4_description', 'field_6aa008bf62f9b'),
