(55961, 1062, 'flexible_content_2_subheading', 'This will be FAQs description.'),
(55962, 1062, '_flexible_content_2_subheading', 'field_6aa00910843b2_field_6944faebb2df2'),
(55963, 1062, 'flexible_content_2_items_0_heading', 'How often should I visit the dentist?'),
(55964, 1062, '_flexible_content_2_items_0_heading', 'field_6aa0088362f9a'),
(55965, 1062, 'flexible_content_2_items_0_description', 'For many people, a routine dental check-up every six months is a useful general guideline. Your dentist may recommend a different schedule depending on your oral health and individual needs.'),
(55966, 1062, '_flexible_content_2_items_0_description', 'field_6aa008bf62f9b'),
(55967, 1062, 'flexible_content_2_items_1_heading', 'Is a root canal treatment painful?'),
(55968, 1062, '_flexible_content_2_items_1_heading', 'field_6aa0088362f9a'),
(55969, 1062, 'flexible_content_2_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(55970, 1062, '_flexible_content_2_items_1_description', 'field_6aa008bf62f9b'),
(55971, 1062, 'flexible_content_2_items_2_heading', 'What are dental implants?'),
(55972, 1062, '_flexible_content_2_items_2_heading', 'field_6aa0088362f9a'),
(55973, 1062, 'flexible_content_2_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(55974, 1062, '_flexible_content_2_items_2_description', 'field_6aa008bf62f9b'),
(55975, 1062, 'flexible_content_2_items_3_heading', 'How can I improve my oral health?'),
(55976, 1062, '_flexible_content_2_items_3_heading', 'field_6aa0088362f9a'),
(55977, 1062, 'flexible_content_2_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(55978, 1062, '_flexible_content_2_items_3_description', 'field_6aa008bf62f9b'),
(55979, 1062, 'flexible_content_2_items_4_heading', 'When should children first visit a dentist?'),
(55980, 1062, '_flexible_content_2_items_4_heading', 'field_6aa0088362f9a'),
