(56729, 1064, '_flexible_content_2_subheading_tag', 'field_6aa00910843b2_field_6944fae8b2df1'),
(56730, 1064, 'flexible_content_2_subheading', 'This will be FAQs description.'),
(56731, 1064, '_flexible_content_2_subheading', 'field_6aa00910843b2_field_6944faebb2df2'),
(56732, 1064, 'flexible_content_2_items_0_heading', 'How often should I visit the dentist?'),
(56733, 1064, '_flexible_content_2_items_0_heading', 'field_6aa0088362f9a'),
(56734, 1064, 'flexible_content_2_items_0_description', 'For many people, a routine dental check-up every six months is a useful general guideline. Your dentist may recommend a different schedule depending on your oral health and individual needs.'),
(56735, 1064, '_flexible_content_2_items_0_description', 'field_6aa008bf62f9b'),
(56736, 1064, 'flexible_content_2_items_1_heading', 'Is a root canal treatment painful?'),
(56737, 1064, '_flexible_content_2_items_1_heading', 'field_6aa0088362f9a'),
(56738, 1064, 'flexible_content_2_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(56739, 1064, '_flexible_content_2_items_1_description', 'field_6aa008bf62f9b'),
(56740, 1064, 'flexible_content_2_items_2_heading', 'What are dental implants?'),
(56741, 1064, '_flexible_content_2_items_2_heading', 'field_6aa0088362f9a'),
(56742, 1064, 'flexible_content_2_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(56743, 1064, '_flexible_content_2_items_2_description', 'field_6aa008bf62f9b'),
(56744, 1064, 'flexible_content_2_items_3_heading', 'How can I improve my oral health?'),
(56745, 1064, '_flexible_content_2_items_3_heading', 'field_6aa0088362f9a'),
(56746, 1064, 'flexible_content_2_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(56747, 1064, '_flexible_content_2_items_3_description', 'field_6aa008bf62f9b'),
(56748, 1064, 'flexible_content_2_items_4_heading', 'When should children first visit a dentist?'),
(56749, 1064, '_flexible_content_2_items_4_heading', 'field_6aa0088362f9a'),
(56750, 1064, 'flexible_content_2_items_4_description', 'Children should have their first dental visit when their first tooth appears or by their first birthday, followed by regular dental visits as recommended by their dentist.'),
(56751, 1064, '_flexible_content_2_items_4_description', 'field_6aa008bf62f9b'),
(56752, 1064, 'flexible_content_2_items', '5'),
