(57426, 1065, 'flexible_content_1_wrapper_width', ''),
(57427, 1065, '_flexible_content_1_wrapper_width', 'field_6aa0088362f93_field_6a576c811527a'),
(57428, 1065, 'flexible_content_1_heading_tag', 'h2'),
(57429, 1065, '_flexible_content_1_heading_tag', 'field_6aa00910843b2_field_68459c3a1bfb5'),
(57430, 1065, 'flexible_content_1_heading', 'FAQs Heading Here'),
(57431, 1065, '_flexible_content_1_heading', 'field_6aa00910843b2_field_68459c931bfb6'),
(57432, 1065, 'flexible_content_1_subheading_tag', 'h3'),
(57433, 1065, '_flexible_content_1_subheading_tag', 'field_6aa00910843b2_field_6944fae8b2df1'),
(57434, 1065, 'flexible_content_1_subheading', 'This will be FAQs description.'),
(57435, 1065, '_flexible_content_1_subheading', 'field_6aa00910843b2_field_6944faebb2df2'),
(57436, 1065, 'flexible_content_1_items_0_heading', 'How often should I visit the dentist?'),
(57437, 1065, '_flexible_content_1_items_0_heading', 'field_6aa0088362f9a'),
(57438, 1065, 'flexible_content_1_items_0_description', 'For many people, a routine dental check-up every six months is a useful general guideline. Your dentist may recommend a different schedule depending on your oral health and individual needs.'),
(57439, 1065, '_flexible_content_1_items_0_description', 'field_6aa008bf62f9b'),
(57440, 1065, 'flexible_content_1_items_1_heading', 'Is a root canal treatment painful?'),
(57441, 1065, '_flexible_content_1_items_1_heading', 'field_6aa0088362f9a'),
(57442, 1065, 'flexible_content_1_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(57443, 1065, '_flexible_content_1_items_1_description', 'field_6aa008bf62f9b'),
(57444, 1065, 'flexible_content_1_items_2_heading', 'What are dental implants?'),
(57445, 1065, '_flexible_content_1_items_2_heading', 'field_6aa0088362f9a'),
(57446, 1065, 'flexible_content_1_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(57447, 1065, '_flexible_content_1_items_2_description', 'field_6aa008bf62f9b'),
(57448, 1065, 'flexible_content_1_items_3_heading', 'How can I improve my oral health?'),
(57449, 1065, '_flexible_content_1_items_3_heading', 'field_6aa0088362f9a'),
(57450, 1065, 'flexible_content_1_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(57451, 1065, '_flexible_content_1_items_3_description', 'field_6aa008bf62f9b'),
(57452, 1065, 'flexible_content_1_items_4_heading', 'When should children first visit a dentist?'),
(57453, 1065, '_flexible_content_1_items_4_heading', 'field_6aa0088362f9a'),
(57454, 1065, 'flexible_content_1_items_4_description', 'Children should have their first dental visit when their first tooth appears or by their first birthday, followed by regular dental visits as recommended by their dentist.'),
(57455, 1065, '_flexible_content_1_items_4_description', 'field_6aa008bf62f9b'),
