(58200, 1066, 'flexible_content_1_subheading_tag', 'h3'),
(58201, 1066, '_flexible_content_1_subheading_tag', 'field_6aa00910843b2_field_6944fae8b2df1'),
(58202, 1066, 'flexible_content_1_subheading', 'This will be FAQs description.'),
(58203, 1066, '_flexible_content_1_subheading', 'field_6aa00910843b2_field_6944faebb2df2'),
(58204, 1066, 'flexible_content_1_items_0_heading', 'How often should I visit the dentist?'),
(58205, 1066, '_flexible_content_1_items_0_heading', 'field_6aa0088362f9a'),
(58206, 1066, 'flexible_content_1_items_0_description', 'For many people, a routine dental check-up every six months is a useful general guideline. Your dentist may recommend a different schedule depending on your oral health and individual needs.'),
(58207, 1066, '_flexible_content_1_items_0_description', 'field_6aa008bf62f9b'),
(58208, 1066, 'flexible_content_1_items_1_heading', 'Is a root canal treatment painful?'),
(58209, 1066, '_flexible_content_1_items_1_heading', 'field_6aa0088362f9a'),
(58210, 1066, 'flexible_content_1_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(58211, 1066, '_flexible_content_1_items_1_description', 'field_6aa008bf62f9b'),
(58212, 1066, 'flexible_content_1_items_2_heading', 'What are dental implants?'),
(58213, 1066, '_flexible_content_1_items_2_heading', 'field_6aa0088362f9a'),
(58214, 1066, 'flexible_content_1_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(58215, 1066, '_flexible_content_1_items_2_description', 'field_6aa008bf62f9b'),
(58216, 1066, 'flexible_content_1_items_3_heading', 'How can I improve my oral health?'),
(58217, 1066, '_flexible_content_1_items_3_heading', 'field_6aa0088362f9a'),
(58218, 1066, 'flexible_content_1_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(58219, 1066, '_flexible_content_1_items_3_description', 'field_6aa008bf62f9b'),
(58220, 1066, 'flexible_content_1_items_4_heading', 'When should children first visit a dentist?'),
(58221, 1066, '_flexible_content_1_items_4_heading', 'field_6aa0088362f9a'),
(58222, 1066, 'flexible_content_1_items_4_description', 'Children should have their first dental visit when their first tooth appears or by their first birthday, followed by regular dental visits as recommended by their dentist.'),
(58223, 1066, '_flexible_content_1_items_4_description', 'field_6aa008bf62f9b'),
