(59790, 1068, 'flexible_content_2_faqs_open_settings', 'anyOpen'),
(59791, 1068, '_flexible_content_2_faqs_open_settings', 'field_6aa00aa407ebc'),
(59792, 1068, 'flexible_content_2_heading_tag', 'h2'),
(59793, 1068, '_flexible_content_2_heading_tag', 'field_6aa00910843b2_field_68459c3a1bfb5'),
(59794, 1068, 'flexible_content_2_heading', 'FAQs Heading Here'),
(59795, 1068, '_flexible_content_2_heading', 'field_6aa00910843b2_field_68459c931bfb6'),
(59796, 1068, 'flexible_content_2_subheading_tag', 'h3'),
(59797, 1068, '_flexible_content_2_subheading_tag', 'field_6aa00910843b2_field_6944fae8b2df1'),
(59798, 1068, 'flexible_content_2_subheading', 'This will be FAQs description.'),
(59799, 1068, '_flexible_content_2_subheading', 'field_6aa00910843b2_field_6944faebb2df2'),
(59800, 1068, 'flexible_content_2_items_0_heading', 'How often should I visit the dentist?'),
(59801, 1068, '_flexible_content_2_items_0_heading', 'field_6aa0088362f9a'),
(59802, 1068, 'flexible_content_2_items_0_description', 'For many people, a routine dental check-up every six months is a useful general guideline. Your dentist may recommend a different schedule depending on your oral health and individual needs.'),
(59803, 1068, '_flexible_content_2_items_0_description', 'field_6aa008bf62f9b'),
(59804, 1068, 'flexible_content_2_items_1_heading', 'Is a root canal treatment painful?'),
(59805, 1068, '_flexible_content_2_items_1_heading', 'field_6aa0088362f9a'),
(59806, 1068, 'flexible_content_2_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(59807, 1068, '_flexible_content_2_items_1_description', 'field_6aa008bf62f9b'),
(59808, 1068, 'flexible_content_2_items_2_heading', 'What are dental implants?'),
(59809, 1068, '_flexible_content_2_items_2_heading', 'field_6aa0088362f9a'),
(59810, 1068, 'flexible_content_2_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(59811, 1068, '_flexible_content_2_items_2_description', 'field_6aa008bf62f9b'),
(59812, 1068, 'flexible_content_2_items_3_heading', 'How can I improve my oral health?'),
(59813, 1068, '_flexible_content_2_items_3_heading', 'field_6aa0088362f9a'),
(59814, 1068, 'flexible_content_2_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(59815, 1068, '_flexible_content_2_items_3_description', 'field_6aa008bf62f9b'),
(59816, 1068, 'flexible_content_2_items_4_heading', 'When should children first visit a dentist?'),
(59817, 1068, '_flexible_content_2_items_4_heading', 'field_6aa0088362f9a'),
(59818, 1068, 'flexible_content_2_items_4_description', 'Children should have their first dental visit when their first tooth appears or by their first birthday, followed by regular dental visits as recommended by their dentist.'),
(59819, 1068, '_flexible_content_2_items_4_description', 'field_6aa008bf62f9b'),
(59820, 1068, 'flexible_content_2_items', '5'),
