(60503, 1070, '_flexible_content_1_heading_tag', 'field_6aa00910843b2_field_68459c3a1bfb5'),
(60504, 1070, 'flexible_content_1_heading', 'FAQs Heading Here'),
(60505, 1070, '_flexible_content_1_heading', 'field_6aa00910843b2_field_68459c931bfb6'),
(60506, 1070, 'flexible_content_1_subheading_tag', 'h3'),
(60507, 1070, '_flexible_content_1_subheading_tag', 'field_6aa00910843b2_field_6944fae8b2df1'),
(60508, 1070, 'flexible_content_1_subheading', 'This will be FAQs description.'),
(60509, 1070, '_flexible_content_1_subheading', 'field_6aa00910843b2_field_6944faebb2df2'),
(60510, 1070, 'flexible_content_1_items_0_heading', 'How often should I visit the dentist?'),
(60511, 1070, '_flexible_content_1_items_0_heading', 'field_6aa0088362f9a'),
(60512, 1070, 'flexible_content_1_items_0_description', 'For many people, a routine dental check-up every six months is a useful general guideline. Your dentist may recommend a different schedule depending on your oral health and individual needs.'),
(60513, 1070, '_flexible_content_1_items_0_description', 'field_6aa008bf62f9b'),
(60514, 1070, 'flexible_content_1_items_1_heading', 'Is a root canal treatment painful?'),
(60515, 1070, '_flexible_content_1_items_1_heading', 'field_6aa0088362f9a'),
(60516, 1070, 'flexible_content_1_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(60517, 1070, '_flexible_content_1_items_1_description', 'field_6aa008bf62f9b'),
(60518, 1070, 'flexible_content_1_items_2_heading', 'What are dental implants?'),
(60519, 1070, '_flexible_content_1_items_2_heading', 'field_6aa0088362f9a'),
(60520, 1070, 'flexible_content_1_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(60521, 1070, '_flexible_content_1_items_2_description', 'field_6aa008bf62f9b'),
(60522, 1070, 'flexible_content_1_items_3_heading', 'How can I improve my oral health?'),
(60523, 1070, '_flexible_content_1_items_3_heading', 'field_6aa0088362f9a'),
(60524, 1070, 'flexible_content_1_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(60525, 1070, '_flexible_content_1_items_3_description', 'field_6aa008bf62f9b'),
(60526, 1070, 'flexible_content_1_items_4_heading', 'When should children first visit a dentist?'),
(60527, 1070, '_flexible_content_1_items_4_heading', 'field_6aa0088362f9a'),
(60528, 1070, 'flexible_content_1_items_4_description', 'Children should have their first dental visit when their first tooth appears or by their first birthday, followed by regular dental visits as recommended by their dentist.'),
(60529, 1070, '_flexible_content_1_items_4_description', 'field_6aa008bf62f9b'),
