(63602, 1077, 'flexible_content_1_items_1_heading', 'Is a root canal treatment painful?'),
(63603, 1077, '_flexible_content_1_items_1_heading', 'field_6aa0088362f9a'),
(63604, 1077, 'flexible_content_1_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(63605, 1077, '_flexible_content_1_items_1_description', 'field_6aa008bf62f9b'),
(63606, 1077, 'flexible_content_1_items_2_heading', 'What are dental implants?'),
(63607, 1077, '_flexible_content_1_items_2_heading', 'field_6aa0088362f9a'),
(63608, 1077, 'flexible_content_1_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(63609, 1077, '_flexible_content_1_items_2_description', 'field_6aa008bf62f9b'),
(63610, 1077, 'flexible_content_1_items_3_heading', 'How can I improve my oral health?'),
(63611, 1077, '_flexible_content_1_items_3_heading', 'field_6aa0088362f9a'),
(63612, 1077, 'flexible_content_1_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(63613, 1077, '_flexible_content_1_items_3_description', 'field_6aa008bf62f9b'),
(63614, 1077, 'flexible_content_1_items_4_heading', 'When should children first visit a dentist?'),
(63615, 1077, '_flexible_content_1_items_4_heading', 'field_6aa0088362f9a'),
(63616, 1077, 'flexible_content_1_items_4_description', 'Children should have their first dental visit when their first tooth appears or by their first birthday, followed by regular dental visits as recommended by their dentist.'),
(63617, 1077, '_flexible_content_1_items_4_description', 'field_6aa008bf62f9b'),
