(63656, 1077, 'flexible_content_2_subheading', 'This will be FAQs description.'),
(63657, 1077, '_flexible_content_2_subheading', 'field_6aa00910843b2_field_6944faebb2df2'),
(63658, 1077, 'flexible_content_2_items_0_heading', 'How often should I visit the dentist?'),
(63659, 1077, '_flexible_content_2_items_0_heading', 'field_6aa0088362f9a'),
(63660, 1077, 'flexible_content_2_items_0_description', 'For many people, a routine dental check-up every six months is a useful general guideline. Your dentist may recommend a different schedule depending on your oral health and individual needs.'),
(63661, 1077, '_flexible_content_2_items_0_description', 'field_6aa008bf62f9b'),
(63662, 1077, 'flexible_content_2_items_1_heading', 'Is a root canal treatment painful?'),
