(64367, 1078, '_flexible_content_1_subheading_tag', 'field_6aa00910843b2_field_6944fae8b2df1'),
(64368, 1078, 'flexible_content_1_subheading', 'This will be FAQs description.'),
(64369, 1078, '_flexible_content_1_subheading', 'field_6aa00910843b2_field_6944faebb2df2'),
(64370, 1078, 'flexible_content_1_items_0_heading', 'How often should I visit the dentist?'),
(64371, 1078, '_flexible_content_1_items_0_heading', 'field_6aa0088362f9a'),
(64372, 1078, 'flexible_content_1_items_0_description', 'For many people, a routine dental check-up every six months is a useful general guideline. Your dentist may recommend a different schedule depending on your oral health and individual needs.'),
(64373, 1078, '_flexible_content_1_items_0_description', 'field_6aa008bf62f9b'),
(64374, 1078, 'flexible_content_1_items_1_heading', 'Is a root canal treatment painful?'),
(64375, 1078, '_flexible_content_1_items_1_heading', 'field_6aa0088362f9a');
INSERT INTO `wp_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(64376, 1078, 'flexible_content_1_items_1_description', '<p class=\"isSelectedEnd\">Modern dental techniques and local anesthesia can make root canal treatment considerably more comfortable. The purpose of treatment is to remove infection and help relieve pain caused by a damaged or infected tooth.</p>'),
(64377, 1078, '_flexible_content_1_items_1_description', 'field_6aa008bf62f9b'),
(64378, 1078, 'flexible_content_1_items_2_heading', 'What are dental implants?'),
(64379, 1078, '_flexible_content_1_items_2_heading', 'field_6aa0088362f9a'),
(64380, 1078, 'flexible_content_1_items_2_description', '<p class=\"isSelectedEnd\">Dental implants are used to replace missing teeth. They consist of an implant placed in the jawbone and a restoration designed to look and function like a natural tooth.</p>'),
(64381, 1078, '_flexible_content_1_items_2_description', 'field_6aa008bf62f9b'),
(64382, 1078, 'flexible_content_1_items_3_heading', 'How can I improve my oral health?'),
(64383, 1078, '_flexible_content_1_items_3_heading', 'field_6aa0088362f9a'),
(64384, 1078, 'flexible_content_1_items_3_description', '<p class=\"isSelectedEnd\">Brushing twice a day with fluoride toothpaste, cleaning between your teeth, maintaining a balanced diet, limiting excessive sugar intake, and visiting your dentist regularly can all contribute to better oral health.</p>'),
(64385, 1078, '_flexible_content_1_items_3_description', 'field_6aa008bf62f9b'),
(64386, 1078, 'flexible_content_1_items_4_heading', 'When should children first visit a dentist?'),
(64387, 1078, '_flexible_content_1_items_4_heading', 'field_6aa0088362f9a'),
(64388, 1078, 'flexible_content_1_items_4_description', 'Children should have their first dental visit when their first tooth appears or by their first birthday, followed by regular dental visits as recommended by their dentist.'),
(64389, 1078, '_flexible_content_1_items_4_description', 'field_6aa008bf62f9b'),
