INSERT INTO `wp_ucm_queue` (`id`, `run_id`, `item_type`, `source_id`, `source_ref`, `title`, `priority`, `status`, `attempts`, `dest_id`, `message`, `payload`, `result`, `updated_at`) VALUES
(326, 3, 'post', '685', 'https://summitsalonacademy.edu/box-sets/', 'Box sets', 50, 'done', 1, 999, '', '{\"id\":685,\"date\":\"2015-03-23T15:15:50\",\"date_gmt\":\"2015-03-23T23:15:50\",\"guid\":{\"rendered\":\"https:\\/\\/summitsalonacademy.edu\\/?p=685\"},\"modified\":\"2015-03-23T15:15:50\",\"modified_gmt\":\"2015-03-23T23:15:50\",\"slug\":\"box-sets\",\"status\":\"publish\",\"type\":\"post\",\"link\":\"https:\\/\\/summitsalonacademy.edu\\/box-sets\\/\",\"title\":{\"rendered\":\"Box sets\"},\"content\":{\"rendered\":\"<h1>Love the Look Box Sets!<\\/h1>\\n<p>We all know that choosing\\u00a0the correct product to use for the look you want can be overwhelming. Well, we are here to help you!\\u00a0Come in today for your <a href=\\\"http:\\/\\/redken.com\\\">Redken<\\/a> Love the Look Box Sets! These amazing box sets have a full sized styling product, travel sizes of Redken Pillow Proof Primer and Extender and a styling tool! Seems pretty great, right? Well we decided to make this great deal even greater. While supplies last, all Redken box sets are 25% off of the already low prices. That means\\u00a0you are looking at up to 49% savings! \\u00a0Each one of these box sets contains a\\u00a0Redken Essential\\u00a0<em>full-sized<\\/em> styling product, travel sized Pillow Proof Primer, travel sized Pillow Proof extender AND a free brush or comb! Plus step by step instructions on how to get the look you love!<\\/p>\\n<h2>Go Big Or Go Home<\\/h2>\\n<p><a href=\\\"\\/wp-content\\/uploads\\/2015\\/03\\/go-big-or-go-home.jpg\\\"><img loading=\\\"lazy\\\" decoding=\\\"async\\\" class=\\\"alignleft wp-image-689 size-medium\\\" src=\\\"\\/wp-content\\/uploads\\/2015\\/03\\/go-big-or-go-home-280x300.jpg\\\" alt=\\\"go big or go home\\\" width=\\\"280\\\" height=\\\"300\\\" srcset=\\\"https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2015\\/03\\/go-big-or-go-home-280x300.jpg 280w, https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2015\\/03\\/go-big-or-go-home-768x823.jpg 768w, https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2015\\/03\\/go-big-or-go-home-955x1024.jpg 955w, https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2015\\/03\\/go-big-or-go-home-373x400.jpg 373w, https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2015\\/03\\/go-big-or-go-home-560x600.jpg 560w, https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2015\\/03\\/go-big-or-go-home-550x590.jpg 550w\\\" sizes=\\\"auto, (max-width: 280px) 100vw, 280px\\\" \\/><\\/a><\\/p>\\n<p>Go Big or Go Home\\u00a0contains a full sized <a href=\\\"http:\\/\\/www.redken.com\\/products\\/styling\\/volume\\/guts-10-volume-spray-foam\\\">Redken Guts 1<\\/a>0 Volumizing Spray Foam, a travel sized <a href=\\\"http:\\/\\/www.redken.com\\/products\\/styling\\/blow-dry\\/pillow-proof-blow-dry-express-primer-with-heat-protection\\\">Redken Pillow Proof Blow Dry Express Primer<\\/a>, a travel sized <a href=\\\"http:\\/\\/www.redken.com\\/products\\/styling\\/blow-dry\\/pillow-proof-blow-dry-two-day-extender-oil-absorbing-dry-shampoo\\\">Redken Pillow Proof Blow Dry Two Day Extender<\\/a>\\u00a0and a round brush for a blowout with volume! If you love va-va-voom Old Hollywood, glamorous\\u00a0volume, this is the box set\\u00a0for you! Current sale price is $24!<\\/p>\\n<p>&nbsp;<\\/p>\\n<p>&nbsp;<\\/p>\\n<p>&nbsp;<\\/p>\\n<p>&nbsp;<\\/p>\\n<p>&nbsp;<\\/p>\\n<p>&nbsp;<\\/p>\\n<p>&nbsp;<\\/p>\\n<p>&nbsp;<\\/p>\\n<h2>Heat Up Your Style<\\/h2>\\n<p><a href=\\\"\\/wp-content\\/uploads\\/2015\\/03\\/heat-up-your-style.jpg\\\"><img loading=\\\"lazy\\\" decoding=\\\"async\\\" class=\\\"alignleft wp-image-687 size-medium\\\" src=\\\"\\/wp-content\\/uploads\\/2015\\/03\\/heat-up-your-style-276x300.jpg\\\" alt=\\\"heat up your style\\\" width=\\\"276\\\" height=\\\"300\\\" srcset=\\\"https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2015\\/03\\/heat-up-your-style-276x300.jpg 276w, https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2015\\/03\\/heat-up-your-style-768x834.jpg 768w, https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2015\\/03\\/heat-up-your-style-943x1024.jpg 943w, https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2015\\/03\\/heat-up-your-style-368x400.jpg 368w, https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2015\\/03\\/heat-up-your-style-552x600.jpg 552w, https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2015\\/03\\/heat-up-your-style-550x597.jpg 550w\\\" sizes=\\\"auto, (max-width: 276px) 100vw, 276px\\\" \\/><\\/a><\\/p>\\n<p>Heat up your style contains a full sized <a href=\\\"http:\\/\\/www.redken.com\\/products\\/styling\\/heat-styling\\/iron-shape-11-finishing-thermal-spray-heat-protection-hair-spray\\\">Redken Iron Shape 11<\\/a>\\u00a0Thermal Protecting Spray,\\u00a0a travel sized <a href=\\\"http:\\/\\/www.redken.com\\/products\\/styling\\/blow-dry\\/pillow-proof-blow-dry-express-primer-with-heat-protection\\\">Redken Pillow Proof Blow Dry Express Primer<\\/a>, a travel sized <a href=\\\"http:\\/\\/www.redken.com\\/products\\/styling\\/blow-dry\\/pillow-proof-blow-dry-two-day-extender-oil-absorbing-dry-shampoo\\\">Redken Pillow Proof Blow Dry Two Day Extender<\\/a>, and a paddle brush for a sleek look. If you\\u00a0are addicted to your heat styling tools, and love a sleek sophisticated look, pick one of these box sets\\u00a0up today! Current sale price is $24.<\\/p>\\n<p>&nbsp;<\\/p>\\n<p>&nbsp;<\\/p>\\n<p>&nbsp;<\\/p>\\n<p>&nbsp;<\\/p>\\n<p>&nbsp;<\\/p>\\n<p>&nbsp;<\\/p>\\n<p>&nbsp;<\\/p>\\n<p>&nbsp;<\\/p>\\n<h2>Make Waves<\\/h2>\\n<p><a href=\\\"\\/wp-content\\/uploads\\/2015\\/03\\/make-waves.jpg\\\"><img loading=\\\"lazy\\\" decoding=\\\"async\\\" class=\\\"alignleft size-medium wp-image-688\\\" src=\\\"\\/wp-content\\/uploads\\/2015\\/03\\/make-waves-269x300.jpg\\\" alt=\\\"make waves\\\" width=\\\"269\\\" height=\\\"300\\\" srcset=\\\"https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2015\\/03\\/make-waves-269x300.jpg 269w, https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2015\\/03\\/make-waves-768x856.jpg 768w, https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2015\\/03\\/make-waves-919x1024.jpg 919w, https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2015\\/03\\/make-waves-359x400.jpg 359w, https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2015\\/03\\/make-waves-538x600.jpg 538w, https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2015\\/03\\/make-waves-550x613.jpg 550w\\\" sizes=\\\"auto, (max-width: 269px) 100vw, 269px\\\" \\/><\\/a>Make Waves contains R<a href=\\\"http:\\/\\/www.redken.com\\/products\\/styling\\/texture\\/fashion-waves-07\\\">edken Fashion Waves 07 <\\/a>Texturizing Sea Spray,\\u00a0a travel sized <a href=\\\"http:\\/\\/www.redken.com\\/products\\/styling\\/blow-dry\\/pillow-proof-blow-dry-express-primer-with-heat-protection\\\">Redken Pillow Proof Blow Dry Express Primer<\\/a>, a travel sized <a href=\\\"http:\\/\\/www.redken.com\\/products\\/styling\\/blow-dry\\/pillow-proof-blow-dry-two-day-extender-oil-absorbing-dry-shampoo\\\">Redken Pillow Proof Blow Dry Two Day Extender<\\/a>, and a wide tooth comb for creating the perfect tangle free waves! This box set gives you everything you need for a perfect touseled beachy wave siren look. Current sale price is $24.75.<\\/p>\\n<p>&nbsp;<\\/p>\\n<p>&nbsp;<\\/p>\\n<p>&nbsp;<\\/p>\\n<p>&nbsp;<\\/p>\\n<p>&nbsp;<\\/p>\\n<p>&nbsp;<\\/p>\\n<p>&nbsp;<\\/p>\\n<p>&nbsp;<\\/p>\\n<h2>Be A Tease<\\/h2>\\n<p><a href=\\\"\\/wp-content\\/uploads\\/2015\\/03\\/be-a-tease.jpg\\\"><img loading=\\\"lazy\\\" decoding=\\\"async\\\" class=\\\"alignleft size-medium wp-image-690\\\" src=\\\"\\/wp-content\\/uploads\\/2015\\/03\\/be-a-tease-280x300.jpg\\\" alt=\\\"be a tease\\\" width=\\\"280\\\" height=\\\"300\\\" srcset=\\\"https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2015\\/03\\/be-a-tease-280x300.jpg 280w, https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2015\\/03\\/be-a-tease-768x824.jpg 768w, https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2015\\/03\\/be-a-tease-954x1024.jpg 954w, https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2015\\/03\\/be-a-tease-373x400.jpg 373w, https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2015\\/03\\/be-a-tease-559x600.jpg 559w, https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2015\\/03\\/be-a-tease-550x590.jpg 550w\\\" sizes=\\\"auto, (max-width: 280px) 100vw, 280px\\\" \\/><\\/a>Be a tease includes <a href=\\\"http:\\/\\/www.redken.com\\/products\\/styling\\/hairsprays\\/wind-blown-05-dry-finishing-spray\\\">Redken Windblown 05 <\\/a>Dry Finishing Hair Spray,\\u00a0a travel sized <a href=\\\"http:\\/\\/www.redken.com\\/products\\/styling\\/blow-dry\\/pillow-proof-blow-dry-express-primer-with-heat-protection\\\">Redken Pillow Proof Blow Dry Express Primer<\\/a>, a travel sized <a href=\\\"http:\\/\\/www.redken.com\\/products\\/styling\\/blow-dry\\/pillow-proof-blow-dry-two-day-extender-oil-absorbing-dry-shampoo\\\">Redken Pillow Proof Blow Dry Two Day Extender<\\/a>, and a teasing brush for a messy sexy look. This box set is perfect for creating a casual date night look! Current sale price is $26.75.<\\/p>\\n\",\"protected\":false},\"excerpt\":{\"rendered\":\"<p>Love the Look Box Sets! We all know that choosing\\u00a0the correct product to use for the look you want can be overwhelming. Well, we are here to help you!\\u00a0Come in today for your Redken Love the Look Box Sets! These amazing box sets have a full sized styling product, travel sizes of Redken Pillow Proof&#8230;<\\/p>\\n\",\"protected\":false},\"author\":4491,\"featured_media\":686,\"comment_status\":\"open\",\"ping_status\":\"open\",\"sticky\":false,\"template\":\"\",\"format\":\"standard\",\"meta\":{\"_acf_changed\":false,\"footnotes\":\"\"},\"categories\":[15,19,20],\"tags\":[24,64,25,65,66,67,68,69,70,28,71],\"class_list\":[\"post-685\",\"post\",\"type-post\",\"status-publish\",\"for