\"}],\"version-history\":[{\"count\":0,\"href\":\"https:\\/\\/summitsalonacademy.edu\\/wp-json\\/wp\\/v2\\/posts\\/1319\\/revisions\"}],\"wp:featuredmedia\":[{\"embeddable\":true,\"href\":\"https:\\/\\/summitsalonacademy.edu\\/wp-json\\/wp\\/v2\\/media\\/1323\"}],\"wp:attachment\":[{\"href\":\"https:\\/\\/summitsalonacademy.edu\\/wp-json\\/wp\\/v2\\/media?parent=1319\"}],\"wp:term\":[{\"taxonomy\":\"category\",\"embeddable\":true,\"href\":\"https:\\/\\/summitsalonacademy.edu\\/wp-json\\/wp\\/v2\\/categories?post=1319\"},{\"taxonomy\":\"post_tag\",\"embeddable\":true,\"href\":\"https:\\/\\/summitsalonacademy.edu\\/wp-json\\/wp\\/v2\\/tags?post=1319\"}],\"curies\":[{\"name\":\"wp\",\"href\":\"https:\\/\\/api.w.org\\/{rel}\",\"templated\":true}]}}', '{\"source_id\":\"1319\",\"source_url\":\"https:\\/\\/summitsalonacademy.edu\\/sam-villa-summit\\/\",\"dest_id\":1020,\"dest_url\":\"http:\\/\\/localhost:8888\\/rnd\\/2016\\/05\\/12\\/sam-villa-summit\\/\",\"title\":\"Sam Villa at Summit!\",\"author\":\"admin\",\"featured\":\"\",\"inline_images\":12,\"failed_images\":0,\"reused_images\":0,\"comments\":2,\"terms\":7,\"builders\":[],\"warnings\":[],\"fidelity\":\"rendered\",\"failed_urls\":[]}', '2026-08-27 10:51:54');
