INSERT INTO `wp_ucm_queue` (`id`, `run_id`, `item_type`, `source_id`, `source_ref`, `title`, `priority`, `status`, `attempts`, `dest_id`, `message`, `payload`, `result`, `updated_at`) VALUES
(380, 3, 'post', '2346', 'https://summitsalonacademy.edu/3rd-annual-hair-bra-zaar-benefitting-wings-of-karen/', '3rd Annual Hair BRA-Zaar Benefitting Wings of Karen', 50, 'done', 1, 1051, '', '{\"id\":2346,\"date\":\"2018-04-27T19:13:29\",\"date_gmt\":\"2018-04-27T19:13:29\",\"guid\":{\"rendered\":\"https:\\/\\/summitsalonacademy.edu\\/?p=2346\"},\"modified\":\"2018-11-12T13:49:07\",\"modified_gmt\":\"2018-11-12T21:49:07\",\"slug\":\"3rd-annual-hair-bra-zaar-benefitting-wings-of-karen\",\"status\":\"publish\",\"type\":\"post\",\"link\":\"https:\\/\\/summitsalonacademy.edu\\/3rd-annual-hair-bra-zaar-benefitting-wings-of-karen\\/\",\"title\":{\"rendered\":\"3rd Annual Hair BRA-Zaar Benefitting Wings of Karen\"},\"content\":{\"rendered\":\"<p>On June 6th, 2018 Summit Salon Academy will host the 3rd Annual Hair BRA-Zaar and Auction Benefit. Last year\\u2019s event was an amazing success and raised $6252! This year, we are \\u201cWigging Out!\\u201d The event will feature creative hair and makeup looks created by students and alumni of the academy. The event will benefit the charity, <a href=\\\"http:\\/\\/www.wingsofkaren.org\\/\\\" target=\\\"_blank\\\" rel=\\\"noopener\\\">Wings of Karen. <\\/a><\\/p>\\n<p><img loading=\\\"lazy\\\" decoding=\\\"async\\\" class=\\\"aligncenter wp-image-2347 size-full\\\" src=\\\"https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2018\\/04\\/unnamed.png\\\" alt=\\\"BRA-Zaar graphic of woman with blue hair in a pink dress.\\\" width=\\\"944\\\" height=\\\"368\\\" srcset=\\\"https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2018\\/04\\/unnamed.png 944w, https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2018\\/04\\/unnamed-300x117.png 300w, https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2018\\/04\\/unnamed-768x299.png 768w, https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2018\\/04\\/unnamed-800x312.png 800w, https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2018\\/04\\/unnamed-550x214.png 550w\\\" sizes=\\\"auto, (max-width: 944px) 100vw, 944px\\\" \\/><\\/p>\\n<p>Buy your tickets <a href=\\\"https:\\/\\/hairbrazaarwigsout.brownpapertickets.com\\/\\\" target=\\\"_blank\\\" rel=\\\"noopener\\\">here<\\/a> or learn more on our <a href=\\\"https:\\/\\/www.facebook.com\\/events\\/295394917660737\\/\\\" target=\\\"_blank\\\" rel=\\\"noopener\\\">Facebook page! <\\/a><\\/p>\\n\",\"protected\":false},\"excerpt\":{\"rendered\":\"<p>On June 6th, 2018 Summit Salon Academy will host the 3rd Annual Hair BRA-Zaar and Auction Benefit. Last year\\u2019s event was an amazing success and raised $6252! This year, we are \\u201cWigging Out!\\u201d The event will feature creative hair and makeup looks created by students and alumni of the academy. The event will benefit the&#8230;<\\/p>\\n\",\"protected\":false},\"author\":4491,\"featured_media\":2347,\"comment_status\":\"open\",\"ping_status\":\"open\",\"sticky\":false,\"template\":\"\",\"format\":\"standard\",\"meta\":{\"_acf_changed\":false,\"footnotes\":\"\"},\"categories\":[154],\"tags\":[],\"class_list\":[\"post-2346\",\"post\",\"type-post\",\"status-publish\",\"format-standard\",\"has-post-thumbnail\",\"hentry\",\"category-community-service\"],\"acf\":[],\"aioseo_notices\":[],\"aioseo_head\":\"\\n\\t\\t<!-- All in One SEO 5.0.0.1 - aioseo.com -->\\n\\t<meta name=\\\"robots\\\" content=\\\"max-snippet:-1, max-image-preview:large, max-video-preview:-1\\\" \\/>\\n\\t<meta name=\\\"author\\\" content=\\\"webdev\\\"\\/>\\n\\t<link rel=\\\"canonical\\\" href=\\\"https:\\/\\/summitsalonacademy.edu\\/3rd-annual-hair-bra-zaar-benefitting-wings-of-karen\\/\\\" \\/>\\n\\t<meta name=\\\"generator\\\" content=\\\"All in One SEO (AIOSEO) 5.0.0.1\\\" \\/>\\n\\t\\t<script type=\\\"application\\/ld+json\\\" class=\\\"aioseo-schema\\\">\\n\\t\\t\\t{\\\"@context\\\":\\\"https:\\\\\\/\\\\\\/schema.org\\\",\\\"@graph\\\":[{\\\"@type\\\":\\\"Article\\\",\\\"@id\\\":\\\"https:\\\\\\/\\\\\\/summitsalonacademy.edu\\\\\\/3rd-