INSERT INTO `wp_ucm_queue` (`id`, `run_id`, `item_type`, `source_id`, `source_ref`, `title`, `priority`, `status`, `attempts`, `dest_id`, `message`, `payload`, `result`, `updated_at`) VALUES
(412, 3, 'post', '3169', 'https://summitsalonacademy.edu/social-promoter-of-the-month-brittany-baldock/', 'Social Promoter of the Month: Brittany Baldock', 50, 'done', 1, 1083, '', '{\"id\":3169,\"date\":\"2019-12-18T12:14:02\",\"date_gmt\":\"2019-12-18T20:14:02\",\"guid\":{\"rendered\":\"https:\\/\\/summitsalonacademy.edu\\/?p=3169\"},\"modified\":\"2019-12-18T13:27:49\",\"modified_gmt\":\"2019-12-18T21:27:49\",\"slug\":\"social-promoter-of-the-month-brittany-baldock\",\"status\":\"publish\",\"type\":\"post\",\"link\":\"https:\\/\\/summitsalonacademy.edu\\/social-promoter-of-the-month-brittany-baldock\\/\",\"title\":{\"rendered\":\"Social Promoter of the Month: Brittany Baldock\"},\"content\":{\"rendered\":\"<p>Get ready for another social promoter blog! At <a href=\\\"\\/\\\" rel=\\\"noopener noreferrer\\\" target=\\\"_blank\\\">Summit Salon Academy Tacoma<\\/a>, we love to highlight our students and the good work they do. Each month we show off one of our students and how they use beauty social media to elevate themselves and their education. This December, meet Brittany Baldock!<\\/p>\\n<h2>About Brittany<\\/h2>\\n<p>Brittany began her beauty journey with Summit just three months ago after working in massage. She says she has always loved makeup and skincare and that enrolling in beauty school felt like a natural next step. She is a wonderful educator about all things skincare and is passionate about learning more! Outside of skincare and beauty, Brittany loves reading, watching movies, and pole dancing! She is a great example of how students at Summit can take their beauty education to the next level.<\\/p>\\n<blockquote class=\\\"instagram-media\\\" data-instgrm-captioned data-instgrm-permalink=\\\"https:\\/\\/www.instagram.com\\/p\\/B5PAKqbhLVl\\/?utm_source=ig_embed&amp;utm_campaign=loading\\\" data-instgrm-version=\\\"12\\\" style=\\\" background:#FFF; border:0; border-radius:3px; box-shadow:0 0 1px 0 rgba(0,0,0,0.5),0 1px 10px 0 rgba(0,0,0,0.15); margin: 1px; max-width:540px; min-width:326px; padding:0; width:99.375%; width:-webkit-calc(100% - 2px); width:calc(100% - 2px);\\\">\\n<div style=\\\"padding:16px;\\\"> <a href=\\\"https:\\/\\/www.instagram.com\\/p\\/B5PAKqbhLVl\\/?utm_source=ig_embed&amp;utm_campaign=loading\\\" style=\\\" background:#FFFFFF; line-height:0; padding:0 0; text-align:center; text-decoration:none; width:100%;\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\"> <\\/p>\\n<div style=\\\" display: flex; flex-direction: row; align-items: center;\\\">\\n<div style=\\\"background-color: #F4F4F4; border-radius: 50%; flex-grow: 0; height: 40px; margin-right: 14px; width: 40px;\\\"><\\/div>\\n<div style=\\\"display: flex; flex-direction: column; flex-grow: 1; justify-content: center;\\\">\\n<div style=\\\" background-color: #F4F4F4; border-radius: 4px; flex-grow: 0; height: 14px; margin-bottom: 6px; width: 100px;\\\"><\\/div>\\n<div style=\\\" background-color: #F4F4F4; border-radius: 4px; flex-grow: 0; height: 14px; width: 60px;\\\"><\\/div>\\n<\\/div>\\n<\\/div>\\n<div style=\\\"padding: 19% 0;\\\"><\\/div>\\n<div style=\\\"display:block; height:50px; margin:0 auto 12px; width:50px;\\\"><svg width=\\\"50px\\\" height=\\\"50px\\\" viewBox=\\\"0 0 60 60\\\" version=\\\"1.1\\\" xmlns=\\\"https:\\/\\/www.w3.org\\/2000\\/svg\\\" xmlns:xlink=\\\"https:\\/\\/www.w3.org\\/1999\\/xlink\\\"><g stroke=\\\"none\\\" stroke-width=\\\"1\\\" fill=\\\"none\\\" fill-rule=\\\"evenodd\\\"><g transform=\\\"translate(-511.000000, -20.000000)\\\" fill=\\\"#000000\\\"><g><path d=\\\"M556.869,30.41 C554.814,30.41 553.148,32.076 553.148,34.131 C553.148,36.186 554.814,37.852 556.869,37.852 C558.924,37.852 560.59,36.186 560.59,34.131 C560.59,32.076 558.924,30.41 556.869,30.41 M541,60.657 C535.114,60.657 530.342,55.887 530.342,50 C530.342,44.114 535.114,39.342 541,39.342 C546.887,39.342 551.658,44.114 551.658,50 C551.658,55.887 546.887,60.657 541,60.657 M541,33.886 C532.1,33.886 524.886,41.1 524.886,50 C524.886,58.899 532.