INSERT INTO `wp_ucm_queue` (`id`, `run_id`, `item_type`, `source_id`, `source_ref`, `title`, `priority`, `status`, `attempts`, `dest_id`, `message`, `payload`, `result`, `updated_at`) VALUES
(414, 3, 'post', '3197', 'https://summitsalonacademy.edu/social-promoter-of-the-month-xiomara-navarrete/', 'Social Promoter of the Month: Xiomara Navarrete', 50, 'done', 1, 1085, '', '{\"id\":3197,\"date\":\"2020-03-02T13:23:21\",\"date_gmt\":\"2020-03-02T21:23:21\",\"guid\":{\"rendered\":\"https:\\/\\/summitsalonacademy.edu\\/?p=3197\"},\"modified\":\"2020-03-02T13:23:21\",\"modified_gmt\":\"2020-03-02T21:23:21\",\"slug\":\"social-promoter-of-the-month-xiomara-navarrete\",\"status\":\"publish\",\"type\":\"post\",\"link\":\"https:\\/\\/summitsalonacademy.edu\\/social-promoter-of-the-month-xiomara-navarrete\\/\",\"title\":{\"rendered\":\"Social Promoter of the Month: Xiomara Navarrete\"},\"content\":{\"rendered\":\"<p>We are so excited to announce that February\\u2019s social promoter of the month is Xiomara Navarette. She has been working hard to improve her beauty skills here at Summit Salon Academy Tacoma and is learning how to put her social media skills to great use as well. <\\/p>\\n<h2>About Xiomara<\\/h2>\\n<p>Xiomara came to Washington from California. The move was a big change <q>I was adjusting to the weather and trying to figure what I wanted to do for a living.<\\/q> In the end, Xiomara turned to beauty. She says, \\u201cGrowing up with 4 older sisters I\\u2019ve always watched them get dolled up and that inspired me.\\u201d <\\/p>\\n<blockquote class=\\\"instagram-media\\\" data-instgrm-captioned data-instgrm-permalink=\\\"https:\\/\\/www.instagram.com\\/p\\/B1rXFftHgu5\\/?utm_source=ig_embed&amp;utm_campaign=loading\\\" data-instgrm-version=\\\"12\\\" style=\\\" background:#FFF; border:0; border-radius:3px; box-shadow:0 0 1px 0 rgba(0,0,0,0.5),0 1px 10px 0 rgba(0,0,0,0.15); margin: 1px; max-width:540px; min-width:326px; padding:0; width:99.375%; width:-webkit-calc(100% - 2px); width:calc(100% - 2px);\\\">\\n<div style=\\\"padding:16px;\\\"> <a href=\\\"https:\\/\\/www.instagram.com\\/p\\/B1rXFftHgu5\\/?utm_source=ig_embed&amp;utm_campaign=loading\\\" s