INSERT INTO `wp_ucm_queue` (`id`, `run_id`, `item_type`, `source_id`, `source_ref`, `title`, `priority`, `status`, `attempts`, `dest_id`, `message`, `payload`, `result`, `updated_at`) VALUES
(449, 3, 'post', '5624', 'https://summitsalonacademy.edu/making-headlines-summit-salon-academy-in-tacoma-featured-in-beauty-industry-report/', 'Making Headlines: Summit Salon Academy in Tacoma Featured in Beauty Industry Report', 50, 'done', 1, 1120, '', '{\"id\":5624,\"date\":\"2025-04-04T14:05:39\",\"date_gmt\":\"2025-04-04T21:05:39\",\"guid\":{\"rendered\":\"https:\\/\\/summitsalonacademy.edu\\/?p=5624\"},\"modified\":\"2025-04-04T14:28:34\",\"modified_gmt\":\"2025-04-04T21:28:34\",\"slug\":\"making-headlines-summit-salon-academy-in-tacoma-featured-in-beauty-industry-report\",\"status\":\"publish\",\"type\":\"post\",\"link\":\"https:\\/\\/summitsalonacademy.edu\\/making-headlines-summit-salon-academy-in-tacoma-featured-in-beauty-industry-report\\/\",\"title\":{\"rendered\":\"Making Headlines: Summit Salon Academy in Tacoma Featured in Beauty Industry Report\"},\"content\":{\"rendered\":\"<p><span style=\\\"font-weight: 400;\\\">Summit Salon Academy in Tacoma is making waves in the beauty industry once again! Recently featured in the <\\/span><i><span style=\\\"font-weight: 400;\\\">Beauty Industry Report<\\/span><\\/i><span style=\\\"font-weight: 400;\\\">, our academy was recognized for its outstanding commitment to philanthropy, community engagement, and student empowerment. The feature highlighted our successful <\\/span><i><span style=\\\"font-weight: 400;\\\">Hair BRA-Zaar<\\/span><\\/i><span style=\\\"font-weight: 400;\\\"> event, which raised an impressive $32,000 for the nonprofit HairToStay\\u2019s Sydney Berry Fund.<\\/span><\\/p>\\n<h2><span style=\\\"font-weight: 400;\\\">A Legacy of Giving Back<\\/span><\\/h2>\\n<p><span style=\\\"font-weight: 400;\\\">Since opening in 2006, Karen and Michael Shea, co-owners of Summit Salon Academy in Tacoma, have instilled a culture of giving within the academy. In 2016, they launched the Hair BRA-Zaar, a unique hair and fashion show where students decorate bras to raise funds for breast cancer research.<\\/span><\\/p>\\n<p><span style=\\\"font-weight: 400;\\\">This year, the event surpassed expectations, with over 100 students showcasing their hairstyling and makeup artistry under the fun and creative theme \\u201cIn a Barbie World.\\u201d From hair and makeup to costume design, our students put their talents to work for an incredible cause\\u200b.<\\/span><\\/p>\\n<h2><span style=\\\"font-weight: 400;\\\">Supporting Cancer Patients with HairToStay<\\/span><\\/h2>\\n<p><span style=\\\"font-weight: 400;\\\">The funds raised from the event support HairToStay, a national nonprofit that provides financial assistance for scalp cooling treatments. These treatments help cancer patients reduce chemotherapy-induced hair loss, offering them emotional resilience and a sense of normalcy during their treatment.<\\/span><\\/p>\\n<p><span style=\\\"font-weight: 400;\\\">The academy was honored to have Sydney Berry, a 30-year cancer survivor and beauty industry veteran, share her journey with our students. Through her advocacy, our students learned how the beauty industry can support those battling cancer in meaningful ways\\u200b.<\\/span><\\/p>\\n<h2><span style=\\\"font-weight: 400;\\\">Beyond Beauty: Teaching Philanthropy to Future Professionals<\\/span><\\/h2>\\n<p><span style=\\\"font-weight: 400;\\\">At Summit Salon Academy in Tacoma, we believe beauty professionals are more than just hairstylists or makeup artists\\u2014we are caregivers, confidants, and changemakers. The <\\/span><i><span style=\\\"font-weight: 400;\\\">Beauty Industry Report<\\/span><\\/i><span style=\\\"font-weight: 400;\\\"> recognized our efforts in equipping students with not just technical skills but also a heart for service.<\\/span><\\/p>\\n<p><img loading=\\\"lazy\\\" decoding=\\\"async\\\" class=\\\"alignleft wp-image-5625 size-medium\\\" src=\\\"https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2025\\/04\\/Screenshot-2025-04-04-at-3.03.23\\u202fPM-233x300.png\\\" alt=\\\"The Beauty Industry Report\\\" width=\\\"233\\\" height=\\\"300\\\" srcset=\\\"https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2025\\/04\\/Screenshot-2025-04-04-at-3.03.23\\u202fPM-233x300.png 233w, https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2025\\/04\\/Screenshot-2025-04-04-at-3.03.23\\u202fPM-310x400.png 310w, https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2025\\/04\\/Screenshot-2025-04-04-at-3.03.23\\u202fPM.png 452w\\\" sizes=\\\"auto, (max-width: 233px) 100vw, 233px\\\" \\/><img loading=\\\"lazy\\\" decoding=\\\"async\\\" class=\\\"alignleft wp-image-5626 size-medium\\\" src=\\\"https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2025\\/04\\/Screenshot-2025-04-04-at-3.03.43\\u202fPM-231x300.png\\\" alt=\\\"The Beauty Industry Report\\\" width=\\\"231\\\" height=\\\"300\\\" srcset=\\\"https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2025\\/04\\/Screenshot-2025-04-04-at-3.03.43\\u202fPM-231x300.png 231w, https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2025\\/04\\/Screenshot-2025-04-04-at-3.03.43\\u202fPM-308x400.png 308w, https:\\/\\/summitsalonacademy.edu\\/wp-content\\/uploads\\/2025\\/04\\/Screenshot-2025-04-04-at-3.03.43\\u202fPM.png 451w\\\" sizes=\\\"auto, (max-width: 231px) 100vw, 231px\\\" \\/><\\/p>\\n<h2><\\/h2>\\n<h2><\\/h2>\\n<h2><\\/h2>\\n<h2><\\/h2>\\n<h2><\\/h2>\\n<h2><\\/h2>\\n<h2><span style=\\\"font-weight: 400;\\\">The Future is Bright<\\/span><\\/h2>\\n<p><span style=\\\"font-weight: 400;\\\">Summit Salon Academy in Tacoma is honored to be featured in the <\\/span><i><span style=\\\"font-weight: 400;\\\">Beauty Industry Report<\\/span><\\/i><span style=\\\"font-weight: 400;\\\">, and we remain committed to making a difference. Whether it&#8217;s through beauty education, community service, or student empowerment, we are proud to be at the forefront of beauty with a purpose.<\\/span><\\/p>\\n\",\"protected\":false},\"excerpt\":{\"rendered\":\"<p>Summit Salon Academy in Tacoma is making waves in the beauty industry once again! Recently featured in the Beauty Industry Report, our academy was recognized for its outstanding commitment to philanthropy, community engagement, and student empowerment. The feature highlighted our successful Hair BRA-Zaar event, which raised an impressive $32,000 for the nonprofit HairToStay\\u2019s Sydney Berry&#8230;<\\/p>\\n\",\"protected\":false},\"author\":4491,\"featured_media\":5630,\"comment_status\":\"closed\",\"ping_status\":\"open\",\"sticky\":false,\"template\":\"\",\"format\":\"standard\",\"meta\":{\"_acf_changed\":false,\"footnotes\":\"\"},\"categories\":[15,162,19],\"tags\":[],\"class_list\":[\"post-5624\",\"post\",\"type-post\",\"status-publish\",\"format-standard\",\"has-post-thumbnail\",\"hentry\",\"category-blog\",\"category-hair-bra-zaar\",\"category-news-events\"],\"acf\":[],\"aioseo_notices\":[],\"aioseo_head\":\"\\n\\t\\t<!-- All in One SEO 5.0.0.1 - aioseo.com -->\\n\\t<meta name=\\\"robots\\\" content=\\\"max-snippet:-1, max-image-preview:large, max-video-preview:-1\\\" \\/>\\n\\t<meta name=\\\"author\\\" content=\\\"webdev\\\"\\/>\\n\\t<link rel=\\\"canonical\\\" href=\\\"https:\\/\\/summitsalonacademy.edu\\/making-headlines-summit-salon-academy-in-tacoma-featured-in-beauty-industry-report\\/\\\" \\/>\\n\\t<meta name=\\\"generator\\\" content=\\\"All in One SEO (AIOSEO) 5.0.0.1\\\" \\/>\\n\\t\\t<script type=\\\"application\\/ld+json\\\" class=\\\"aioseo-schema\\\">\\n\\t\\t\\t{\\\"@context\\\":\\\"https:\\\\\\/\\\\\\/schema.org\\\",\\\"@graph\\\":[{\\\"@type\\\":\\\"Article\\\",\\\"@id\\\":\\\"https:\\\\\\/\\\\\\/summitsalonacademy.edu\\\\\\/making-headlines-summit-salon-academy-in-tacoma-featured-in-beauty-industry-report\\\\\\/#article\\\",\\\"name\\\":\\\"Making Headlines: Summit Salon Academy in Tacoma Featured in Beauty Industry Report | Summit Salon Academy\\\",\\\"headline\\\":\\\"Making Headlines: Summit Salon Academy in Tacoma Featured in Beauty Industry Report\\\",\\\"author\\\":{\\\"@id\\\":\\\"ht