(706, 3, 'comment_src', '89', 'post:2908', '', 40, 'held', 0, 0, NULL, '{\"id\":\"89\",\"parent\":\"85\",\"author_name\":\"Summit Salon Academy Tacoma\",\"author_email\":\"\",\"author_url\":\"\",\"author_id\":\"3\",\"date_gmt\":\"2019-09-10 18:47:36\",\"content\":\"<p>Hi Yvonne! We are so happy that you love your hair!<\\/p>\\n\",\"approved\":\"1\",\"type\":\"\",\"meta\":[]}', NULL, '2026-08-27 10:49:55'),
