INSERT INTO `wp_ucm_queue` (`id`, `run_id`, `item_type`, `source_id`, `source_ref`, `title`, `priority`, `status`, `attempts`, `dest_id`, `message`, `payload`, `result`, `updated_at`) VALUES
(3758, 6, 'post', '738', 'https://emergencydistg.wpenginepowered.com/news/press-releases/12EEBDB9-984A-465B-8E35-A642D3E91851', 'Navigator Draws Record Number to Conference in Salt Lake City', 50, 'done', 1, 1243, '', '{\"id\":738,\"date\":\"2013-05-14T00:00:00\",\"date_gmt\":\"2013-05-14T00:00:00\",\"guid\":{\"rendered\":\"https:\\/\\/emergencydistg.wpenginepowered.com\\/in-the-news\\/uncategorized\\/12EEBDB9-984A-465B-8E35-A642D3E91851\\/\"},\"modified\":\"2026-10-19T10:23:08\",\"modified_gmt\":\"2026-10-19T10:23:08\",\"slug\":\"12eebdb9-984a-465b-8e35-a642d3e91851\",\"status\":\"publish\",\"type\":\"post\",\"link\":\"https:\\/\\/emergencydistg.wpenginepowered.com\\/news\\/press-releases\\/12EEBDB9-984A-465B-8E35-A642D3E91851\",\"title\":{\"rendered\":\"Navigator Draws Record Number to Conference in Salt Lake City\"},\"content\":{\"rendered\":\"\\n<p class=\\\"wp-block-paragraph\\\">The 2013 U.S. NAVIGATOR lived up to its billing as both a gathering and a place &#8220;Different by Nature,&#8221; attracting attendees from 13 countries to Salt Lake City where the seeds of the International Academies of Emergency Dispatch\\u00ae (IAED\\u2122) first rooted.<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">April 17\\u201319 were three days of natural habitat for a record 1,329 attendees who had traveled from as far away &#8220;as the land down under the land down under&#8221;\\u2014Tasmania\\u2014to the most diverse selection of workshops, continuing education, and the widest array of emergency services vendors.<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">Conference-goers also got a taste of Utah&#8217;s famous outdoors indoors during &#8220;The Big Adventure&#8221; get-together the first night that featured requisites for any decent campsite\\u2014barbecue fare, live music, tents, lanterns, and a campfire.<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">Conference-goers said they felt an unusually strong sense of community this year. Some said they felt recharged and uplifted. A group from Long Island, N.Y., said the conference had been as inspirational as the purple mountain majesties of the Wasatch Front that lie directly to the east of downtown.<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">The largest number ever of NAVIGATOR attendees selected from pre-conference classes including the new and timely Active Assailant Workshop and fifteen tracks offered during NAVIGATOR, which included the arcane and always lively (read &#8220;sometimes heated&#8221;) exchange of ideas at the Q Forum Live workshop.<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">Inspiration and personal achievement in the workplace and at home were primary themes of the opening and closing ceremonies&#8217; keynoters. Jim Shea, Jr., a 2002 Winter Olympics Gold Medalist in Men&#8217;s Skeleton\\u2014that&#8217;s the event where you slide down a mile-long bobsled run at 80 mph facedown on a sled the size of a cafeteria tray\\u2014kicked off the conference during the Opening Session.<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">Shea, who called skeleton &#8220;the moonshine of thrills,&#8221; said he achieved gold because he was never satisfied with good enough. &#8220;It&#8217;s that commitment that helped elevate me. Every time I went down the track I was never satisfied.\\\\&#8221;<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\"><strong>About NAVIGATOR<\\/strong><\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">The NAVIGATOR conference presents an event relevant to all in police, fire, and medical emergency communications and offers educational sessions, an exhibit hall, pre-conference workshops, special events, and networking opportunities. NAVIGATOR 2014 will take place April 30\\u2013May 2 at Disney&#8217;s Coronado Springs Resort in Florida.<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\"><strong>About the IAED<\\/strong><\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">The IAED is a non-profit, standard-setting organization promoting safe and effective emergency dispatch services worldwide and comprised of four allied academies for medical, fire, and police dispatching and emergency communication nurses. For more information about the IAED, visit&nbsp;<a href=\\\"https:\\/\\/www.emergencydispatch.org\\/home\\\">www.emergencydispatch.org<\\/a>.<\\/p>\\n\",\"protected\":false},\"excerpt\":{\"rendered\":\"<p>The 2013 U.S. NAVIGATOR lived up to its billing as both a gathering and<br \\/>\\na place &#8220;Different by Nature,&#8221; attracting attendees from 13 countries to<br \\/>\\nSalt Lake City where the seeds of the International Academies of<br \\/>\\nEmergency Dispatch\\u00ae&#8230;<\\/p>\\n\",\"protected\":false},\"author\":1,\"featured_media\":0,\"comment_status\":\"open\",\"ping_status\":\"open\",\"sticky\":false,\"template\":\"\",\"format\":\"standard\",\"meta\":{\"_acf_changed\":false,\"footnotes\":\"\"},\"categories\":[22],\"tags\":[],\"class_list\":[\"post-738\",\"post\",\"type-post\",\"status-publish\",\"format-standard\",\"hentry\",\"category-press-releases\"],\"acf\":[],\"yoast_head\":\"<!-- This site is optimized with the Yoast SEO plugin v28.7 - https:\\/\\/yoast.com\\/product\\/yoast-seo-wordpress\\/ -->\\n<title>Navigator Draws Record Number to Conference in Salt Lake City | Emergency Dispatch<\\/title>\\n<meta name=\\\"robots\\\" content=\\\"noindex, follow, max-snippet:-1, max-image-preview:large, max-video-preview:-1\\\" \\/>\\n<meta property=\\\"og:locale\\\" content=\\\"en_US\\\" \\/>\\n<meta property=\\\"og:type\\\" content=\\\"article\\\" \\/>\\n<meta property=\\\"og:title\\\" content=\\\"Navigator Draws Record Number to Conference in Salt Lake City | Emergency Dispatch\\\" \\/>\\n<meta property=\\\"og:description\\\" content=\\\"The 2013 U.S. NAVIGATOR lived up to its billing as both a gathering and a place &quot;Different by Nature,&quot; attracting attendees from 13 countries to Salt Lake City where the seeds of the International Academies of Emergency Dispatch\\u00ae...\\\" \\/>\\n<meta property=\\\"og:url\\\" content=\\\"https:\\/\\/emergencydistg.wpenginepowered.com\\/news\\/press-releases\\/12EEBDB9-984A-465B-8E35-A642D3E91851\\/\\\" \\/>\\n<meta property=\\\"og:site_name\\\" content=\\\"Emergency Dispatch\\\" \\/>\\n<meta property=\\\"article:published_time\\\" content=\\\"2013-05-14T00:00:00+00:00\\\" \\/>\\n<meta property=\\\"article:modified_time\\\" content=\\\"2026-10-19T10:23:08+00:00\\\" \\/>\\n<meta name=\\\"author\\\" content=\\\"webdev@oozlemedia.com\\\" \\/>\\n<meta name=\\\"twitter:card\\\" content=\\\"summary_large_image\\\" \\/>\\n<meta name=\\\"twitter:label1\\\" content=\\\"Written by\\\" \\/>\\n\\t<meta name=\\\"twitter:data1\\\" content=\\\"webdev@oozlemedia.com\\\" \\/>\\n\\t<meta name=\\\"twitter:label2\\\" content=\\\"Est. reading time\\\" \\/>\\n\\t<meta name=\\\"twitter:data2\\\" content=\\\"2 minutes\\\" \\/>\\n<script type=\\\"application\\/ld+json\\\" class=\\\"yoast-schema-graph\\\">{\\\"@context\\\":\\\"https:\\\\\\/\\\\\\/schema.org\\\",\\\"@graph\\\":[{\\\"@type\\\":\\\"Article\\\",\\\"@id\\\":\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/news\\\\\\/press-releases\\\\\\/12EEBDB9-984A-465B-8E35-A642D3E91851\\\\\\/#article\\\",\\\"isPartOf\\\":{\\\"@id\\\":\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/news\\\\\\/press-releases\\\\\\/12EEBDB9-984A-465B-8E35-A642D3E91851\\\\\\/\\\"},\\\"author\\\":{\\\"name\\\":\\\"webdev@oozlemedia.com\\\",\\\"@id\\\":\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/#\\\\\\/schema\\\\\\/person\\\\\\/338f35ee363eca7c9019764391474b5a\\\"},\\\"headline\\\":\\\"Navigator Draws Record Number to Conference in Salt Lake City\\\",\\\"datePublished\\\":\\\"2013-05-14T00:00:00+00:00\\\",\\\"dateModified\\\":\\\"2026-10-19T10:23:08+00:00\\\",\\\"mainEntityOfPage\\\":{\\\"@id\\\":\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/news\\\\\\/press-releases\\\\\\/12EEBDB9-984A-