},{\"taxonomy\":\"post_tag\",\"embeddable\":true,\"href\":\"https:\\/\\/emergencydistg.wpenginepowered.com\\/wp-json\\/wp\\/v2\\/tags?post=739\"}],\"curies\":[{\"name\":\"wp\",\"href\":\"https:\\/\\/api.w.org\\/{rel}\",\"templated\":true}]}}', '{\"source_id\":\"739\",\"source_url\":\"https:\\/\\/emergencydistg.wpenginepowered.com\\/news\\/press-releases\\/3C6301D8-9269-4F08-82AE-64AB19A2833C\",\"dest_id\":1244,\"dest_url\":\"http:\\/\\/localhost:8888\\/rnd\\/2013\\/05\\/14\\/3c6301d8-9269-4f08-82ae-64ab19a2833c\\/\",\"title\":\"Navigator Honors Emergency Dispatch Experts and Leaders\",\"author\":\"webdev@oozlemedia.com\",\"featured\":\"\",\"inline_images\":0,\"failed_images\":0,\"reused_images\":0,\"comments\":0,\"terms\":1,\"builders\":[],\"warnings\":[],\"fidelity\":\"rendered\",\"failed_urls\":[]}', '2026-10-21 06:54:55');
