 minutes\"},\"schema\":{\"@context\":\"https:\\/\\/schema.org\",\"@graph\":[{\"@type\":\"Article\",\"@id\":\"https:\\/\\/emergencydistg.wpenginepowered.com\\/news\\/official-statements\\/82E0BDE4-D0B9-4374-949F-E4B4957DCEF7\\/#article\",\"isPartOf\":{\"@id\":\"https:\\/\\/emergencydistg.wpenginepowered.com\\/news\\/official-statements\\/82E0BDE4-D0B9-4374-949F-E4B4957DCEF7\\/\"},\"author\":{\"name\":\"webdev@oozlemedia.com\",\"@id\":\"https:\\/\\/emergencydistg.wpenginepowered.com\\/#\\/schema\\/person\\/338f35ee363eca7c9019764391474b5a\"},\"headline\":\"Special Circumstance Downgrading &#038; Triage\",\"datePublished\":\"2022-01-18T00:00:00+00:00\",\"dateModified\":\"2026-10-19T05:56:38+00:00\",\"mainEntityOfPage\":{\"@id\":\"https:\\/\\/emergencydistg.wpenginepowered.com\\/news\\/official-statements\\/82E0BDE4-D0B9-4374-949F-E4B4957DCEF7\\/\"},\"wordCount\":377,\"commentCount\":0,\"image\":{\"@id\":\"https:\\/\\/emergencydistg.wpenginepowered.com\\/news\\/official-statements\\/82E0BDE4-D0B9-4374-949F-E4B4957DCEF7\\/#primaryimage\"},\"thumbnailUrl\":\"https:\\/\\/prioritydispatch.widen.net\\/content\\/jcgsmosrdf\\/png\\/IAED-directive-flag.png?crop=false&amp;position=c&amp;color=ffffffff&amp;u=7cbckq&amp;w=430\",\"articleSection\":[\"Official Statements\"],\"inLanguage\":\"en-US\",\"potentialAction\":[{\"@type\":\"CommentAction\",\"name\":\"Comment\",\"target\":[\"https:\\/\\/emergencydistg.wpenginepowered.com\\/news\\/official-statements\\/82E0BDE4-D0B9-4374-949F-E4B4957DCEF7\\/#respond\"]}]},{\"@type\":\"WebPage\",\"@id\":\"https:\\/\\/emergencydistg.wpenginepowered.com\\/news\\/official-statements\\/82E0BDE4-D0B9-4374-949F-E4B4957DCEF7\\/\",\"url\":\"https:\\/\\/emergencydistg.wpenginepowered.com\\/news\\/official-statements\\/82E0BDE4-D0B9-4374-949F-E4B4957DCEF7\\/\",\"name\":\"Special Circumstance Downgrading & Triage | Emergency Dispatch\",\"isPartOf\":{\"@id\":\"https:\\/\\/emergencydistg.wpenginepowered.com\\/#website\"},\"primaryImageOfPage\":{\"@id\":\"ht