INSERT INTO `wp_ucm_queue` (`id`, `run_id`, `item_type`, `source_id`, `source_ref`, `title`, `priority`, `status`, `attempts`, `dest_id`, `message`, `payload`, `result`, `updated_at`) VALUES
(3800, 6, 'post', '781', 'https://emergencydistg.wpenginepowered.com/news/official-statements/C512BA7C-47C2-4053-A567-471716D4947F', 'Metronome Linked to High-Quality DD-CPR', 50, 'done', 1, 1285, '', '{\"id\":781,\"date\":\"2018-08-16T00:00:00\",\"date_gmt\":\"2018-08-16T00:00:00\",\"guid\":{\"rendered\":\"https:\\/\\/emergencydistg.wpenginepowered.com\\/in-the-news\\/uncategorized\\/C512BA7C-47C2-4053-A567-471716D4947F\\/\"},\"modified\":\"2026-10-19T05:30:33\",\"modified_gmt\":\"2026-10-19T05:30:33\",\"slug\":\"c512ba7c-47c2-4053-a567-471716d4947f\",\"status\":\"publish\",\"type\":\"post\",\"link\":\"https:\\/\\/emergencydistg.wpenginepowered.com\\/news\\/official-statements\\/C512BA7C-47C2-4053-A567-471716D4947F\",\"title\":{\"rendered\":\"Metronome Linked to High-Quality DD-CPR\"},\"content\":{\"rendered\":\"\\n<p class=\\\"wp-block-paragraph\\\">Using a metronome has officially been linked to high-quality Dispatcher-Assisted CPR in a realistic 911 call setting. A new IAED\\u2122 study published in The Journal of Prehospital and Disaster Medicine confirms that using a metronome during Dispatcher-Assisted CPR (DA-CPR) is effective in helping layperson callers achieve high quality CPR\\u2014CPR meeting the target compression rate and compression depth. Check out the <a class=\\\"inline-link\\\" href=\\\"\\/the-science\\/pre-arrival-dispatch-life-support\\/0bfc7d81-e494-463d-8df5-e58b2ee8a4ca\\\" rel=\\\"noreferrer noopener\\\">study abstract<\\/a> on The Journal of Prehospital and Disaster Medicine, and we encourage you to find out if the emergency dispatchers in your center are using a metronome during DA-CPR. Our partners at Priority Dispatch\\u00ae were the first to integrate a metronome into their <a class=\\\"inline-link\\\" target=\\\"_blank\\\" rel=\\\"noreferrer noopener\\\"><\\/a><a target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" href=\\\"https:\\/\\/prioritydispatch.net\\/proqa\\\">ProQA\\u00ae calltaking software<\\/a> in 2008. ProQA guides emergency dispatchers through DA-CPR, with the visual metronome setting the pace for effectively counting 1, 2, 3, 4 with the caller.<\\/p>\\n\\n\\n\\n<div class=\\\"audio-box\\\">Listen to a call where the emergency dispatcher sets the pace for high-quality CPR by counting out loud with the metronome. <audio controls=\\\"\\\"><br><source src=\\\"https:\\/\\/prioritydispatch.widen.net\\/content\\/qtbt3xa9yo\\/mp3\\/metronome_01.mp3?u=7cbckq\\\" type=\\\"audio\\/mpeg\\\"><br><source src=\\\"https:\\/\\/prioritydispatch.widen.net\\/content\\/qtbt3xa9yo\\/mp3\\/metronome_01.mp3?u=7cbckq\\\" type=\\\"audio\\/wav\\\"><br><source src=\\\"https:\\/\\/prioritydispatch.widen.net\\/content\\/qtbt3xa9yo\\/mp3\\/metronome_01.mp3?u=7cbckq\\\" type=\\\"audio\\/ogg\\\"><br>   Audio tag is not supported in this browser.   <br><\\/audio><\\/div>\\n\\n\\n\\n<div class=\\\"audio-box\\\">Listen to a call where the emergency dispatcher doesn&#8217;t count out loud with the metronome and the caller varies compression rate. <audio controls=\\\"\\\"><br><source src=\\\"https:\\/\\/prioritydispatch.widen.net\\/content\\/oagem1obu9\\/mp3\\/Metronome_03.mp3?u=7cbckq\\\" type=\\\"audio\\/mpeg\\\"><br><source src=\\\"https:\\/\\/prioritydispatch.widen.net\\/content\\/oagem1obu9\\/mp3\\/Metronome_03.mp3?u=7cbckq\\\" type=\\\"audio\\/wav\\\"><br><source src=\\\"https:\\/\\/prioritydispatch.widen.net\\/content\\/oagem1obu9\\/mp3\\/Metronome_03.mp3?u=7cbckq\\\" type=\\\"audio\\/ogg\\\"><br>   Audio tag is not supported in this browser.   <br><\\/audio><\\/div>\\n\",\"protected\":false},\"excerpt\":{\"rendered\":\"<p>Using a metronome has officially been linked to high-quality<br \\/>\\nDispatcher-Assisted CPR in a realistic 911 call setting. A new IAED\\u2122 study published in The Journal of Prehospital and Disaster Medicine confirms that using a metronome during&#8230;<\\/p>\\n\",\"protected\":false},\"author\":1,\"featured_media\":0,\"comment_status\":\"open\",\"ping_status\":\"open\",\"sticky\":false,\"template\":\"\",\"format\":\"standard\",\"meta\":{\"_acf_changed\":false,\"footnotes\":\"\"},\"categories\":[23],\"tags\":[],\"class_list\":[\"post-781\",\"post\",\"type-post\",\"status-publish\",\"format-standard\",\"hentry\",\"category-official-statements\"],\"acf\":[],\"yoast_head\":\"<!-- This site is optimized with the Yoast SEO plugin v28.7 - https:\\/\\/yoast.com\\/product\\/yoast-seo-wordpress\\/ -->\\n<title>Metronome Linked to High-Quality DD-CPR | Emergency Dispatch<\\/title>\\n<meta name=\\\"robots\\\" content=\\\"noindex, follow, max-snippet:-1, max-image-preview:large, max-video-preview:-1\\\" \\/>\\n<meta property=\\\"og:locale\\\" content=\\\"en_US\\\" \\/>\\n<meta property=\\\"og:type\\\" content=\\\"article\\\" \\/>\\n<meta property=\\\"og:title\\\" content=\\\"Metronome Linked to High-Quality DD-CPR | Emergency Dispatch\\\" \\/>\\n<meta property=\\\"og:description\\\" content=\\\"Using a metronome has officially been linked to high-quality Dispatcher-Assisted CPR in a realistic 911 call setting. A new IAED\\u2122 study published in The Journal of Prehospital and Disaster Medicine confirms that using a metronome during...\\\" \\/>\\n<meta property=\\\"og:url\\\" content=\\\"https:\\/\\/emergencydistg.wpenginepowered.com\\/news\\/official-statements\\/C512BA7C-47C2-4053-A567-471716D4947F\\/\\\" \\/>\\n<meta property=\\\"og:site_name\\\" content=\\\"Emergency Dispatch\\\" \\/>\\n<meta property=\\\"article:published_time\\\" content=\\\"2018-08-16T00:00:00+00:00\\\" \\/>\\n<meta property=\\\"article:modified_time\\\" content=\\\"2026-10-19T05:30:33+00:00\\\" \\/>\\n<meta name=\\\"author\\\" content=\\\"webdev@oozlemedia.com\\\" \\/>\\n<meta name=\\\"twitter:card\\\" content=\\\"summary_large_image\\\" \\/>\\n<meta name=\\\"twitter:label1\\\" content=\\\"Written by\\\" \\/>\\n\\t<meta name=\\\"twitter:data1\\\" content=\\\"webdev@oozlemedia.com\\\" \\/>\\n\\t<meta name=\\\"twitter:label2\\\" content=\\\"Est. reading time\\\" \\/>\\n\\t<meta name=\\\"twitter:data2\\\" content=\\\"1 minute\\\" \\/>\\n<script type=\\\"application\\/ld+json\\\" class=\\\"yoast-schema-graph\\\">{\\\"@context\\\":\\\"https:\\\\\\/\\\\\\/schema.org\\\",\\\"@graph\\\":[{\\\"@type\\\":\\\"Article\\\",\\\"@id\\\":\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/news\\\\\\/official-statements\\\\\\/C512BA7C-47C2-4053-A567-471716D4947F\\\\\\/#article\\\",\\\"isPartOf\\\":{\\\"@id\\\":\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/news\\\\\\/official-statements\\\\\\/C512BA7C-47C2-4053-A567-471716D4947F\\\\\\/\\\"},\\\"author\\\":{\\\"name\\\":\\\"webdev@oozlemedia.com\\\",\\\"@id\\\":\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/#\\\\\\/schema\\\\\\/person\\\\\\/338f35ee363eca7c9019764391474b5a\\\"},\\\"headline\\\":\\\"Metronome Linked to High-Quality DD-CPR\\\",\\\"datePublished\\\":\\\"2018-08-16T00:00:00+00:00\\\",\\\"dateModified\\\":\\\"2026-10-19T05:30:33+00:00\\\",\\\"mainEntityOfPage\\\":{\\\"@id\\\":\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/news\\\\\\/official-statements\\\\\\/C512BA7C-47C2-4053-A567-471716D4947F\\\\\\/\\\"},\\\"wordCount\\\":191,\\\"commentCount\\\":0,\\\"articleSection\\\":[\\\"Official Statements\\\"],\\\"inLanguage\\\":\\\"en-US\\\",\\\"potentialAction\\\":[{\\\"@type\\\":\\\"CommentAction\\\",\\\"name\\\":\\\"Comment\\\",\\\"target\\\":[\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/news\\\\\\/official-statements\\\\\\/C512BA7C-47C2-4053-A567-471716D4947F\\\\\\/#respond\\\"]}]},{\\\"@type\\\":\\\"WebPage\\\",\\\"@id\\\":\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/news\\\\\\/official-statements\\\\\\/C512BA7C-47C2-4053-A567-471716D4947F\\\\\\/\\\",\\\"url\\\":\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/news\\\\\\/official-statements\\\\\\/C512BA7C-47C2-4053-A567-471716D4947F\\\\\\/\\\",\\\"name\\\":\\\"Metronome Linked to High-Quality DD-CPR | Emergency Dispatch\\\",\\\"isP