INSERT INTO `wp_ucm_queue` (`id`, `run_id`, `item_type`, `source_id`, `source_ref`, `title`, `priority`, `status`, `attempts`, `dest_id`, `message`, `payload`, `result`, `updated_at`) VALUES
(3845, 6, 'post', '828', 'https://emergencydistg.wpenginepowered.com/news/protocol-updates/BB2A8DC8-8472-46B5-A8A3-7854FA6D43FF', 'The IAED is Pleased to Announce PPDS v7.1.59 in the ProQA v5.1.1.52 Spring Maintenance Release', 50, 'done', 1, 1330, '', '{\"id\":828,\"date\":\"2025-04-29T20:05:16\",\"date_gmt\":\"2025-04-29T20:05:16\",\"guid\":{\"rendered\":\"https:\\/\\/emergencydistg.wpenginepowered.com\\/in-the-news\\/uncategorized\\/BB2A8DC8-8472-46B5-A8A3-7854FA6D43FF\\/\"},\"modified\":\"2026-10-19T10:07:58\",\"modified_gmt\":\"2026-10-19T10:07:58\",\"slug\":\"bb2a8dc8-8472-46b5-a8a3-7854fa6d43ff\",\"status\":\"publish\",\"type\":\"post\",\"link\":\"https:\\/\\/emergencydistg.wpenginepowered.com\\/news\\/protocol-updates\\/BB2A8DC8-8472-46B5-A8A3-7854FA6D43FF\",\"title\":{\"rendered\":\"The IAED is Pleased to Announce PPDS v7.1.59 in the ProQA v5.1.1.52 Spring Maintenance Release\"},\"content\":{\"rendered\":\"\\n<figure class=\\\"wp-block-image is-resized image\\\"><img decoding=\\\"async\\\" src=\\\"https:\\/\\/info.prioritydispatch.net\\/l\\/1035463\\/2025-04-21\\/5x34ft\\/1035463\\/1745253978mFKZTrQM\\/PPDS_v7_Email_Header.png\\\" alt=\\\"Police Priority Dispatch System Email Header\\\" style=\\\"aspect-ratio:2.1333333333333333;width:800px;height:auto\\\"\\/><\\/figure>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">&nbsp;<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">We&#8217;re pleased to be releasing a new version of the IAED&#8217;s Police Protocols<strong>, PPDS\\u00ae v7.1.59 (4\\/17\\/2025)<\\/strong>, with this ProQA v5.1.1.52 Maintenance Release. PPDS v7.1 includes extensive updates for suicidal calls and crisis team and alternative response criteria. We strongly encourage you to read the <strong>PPDS v7.1 Update Guide<\\/strong> and watch the in-depth Update Presentation Video on the College to learn more about these critical changes.<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\"><strong>MPDS\\u00ae v14.0.406 (3\\/27\\/2025)<\\/strong> and <strong>FPDS\\u00ae v8.0.836 (4\\/4\\/2025)<\\/strong> are also included in this release, along with in-depth Update Presentation Videos on the College for each.<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">For a quick overview, <a target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" href=\\\"https:\\/\\/vimeo.com\\/1079561364\\/de5eb38934\\\">watch the ProQA v5.1.1.52 Release Highlight Video<\\/a>, and read on for brief, key updates in police, fire, and medical.<\\/p>\\n\\n\\n\\n<h2 class=\\\"wp-block-heading\\\">Release Materials Available:<\\/h2>\\n\\n\\n\\n<ul class=\\\"wp-block-list\\\">\\n<li><strong>ProQA v5.1.1.52 Release Notes<\\/strong><\\/li>\\n\\n\\n\\n<li><strong>ProQA v5.1.1.52 Agency Impact Form<\\/strong><\\/li>\\n\\n\\n\\n<li><strong>PPDS v7.1.59 Update Guide<\\/strong><\\/li>\\n\\n\\n\\n<li><a href=\\\"https:\\/\\/learn.prioritydispatch.net\\/academy\\/my_learning\\/course\\/167771\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\"><strong>PPDS v7.1.59 Update Presentation Video \\u00a0on the College<\\/strong><\\/a><\\/li>\\n\\n\\n\\n<li><a href=\\\"https:\\/\\/learn.prioritydispatch.net\\/academy\\/my_learning\\/course\\/167770\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\"><strong>FPDS v8.0.836 Update Presentation Video \\u00a0on the College<\\/strong><\\/a><\\/li>\\n\\n\\n\\n<li><a href=\\\"https:\\/\\/learn.prioritydispatch.net\\/academy\\/my_learning\\/course\\/167772\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\"><strong>MPDS v14.0.406 Update Presentation Video \\u00a0on the College<\\/strong><\\/a><\\/li>\\n<\\/ul>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\"><strong>Note:<\\/strong> <i>See your new Regional Client Outreach contact information at the end of this email, as well as a link to update your email preferences.<\\/i><\\/p>\\n\\n\\n\\n<h3 class=\\\"wp-block-heading\\\">UPDATE NOW<\\/h3>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\"><strong>Click below<\\/strong> and use your <strong>Emergency Dispatch Learning Portal<\\/strong> login information to access the new <strong>Software Support Portal<\\/strong> and download software files and access release documentation. You&#8217;ll be prompted to create a login if you don&#8217;t already have one.<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">Once in the Portal you&#8217;ll be able to <strong>add colleagues from your agency who would like to receive these communications about maintenance releases.<\\/strong><\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">If you&#8217;re signing in <strong>for the first time<\\/strong>, it may take 24 to 48 hours to be granted access.<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\"><a target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" href=\\\"http:\\/\\/support.prioritydispatch.net\\/\\\">DOWNLOAD SOFTWARE UPDATE &amp; DOCUMENTATION<\\/a><\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">For help updating your software, please contact Software Support at 866-777-3911 or email <a href=\\\"mailto:software.support@prioritydispatch.net\\\">software.support@prioritydispatch.net<\\/a><\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">&nbsp;<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\"><strong>SPECIAL LANGUAGE INFORMATION:<\\/strong><br><i>This initial ProQA v5.1.1.52 release is for English-only users at this time. All other languages for ProQA v5.1.1.52 will be released on May 13, 2025.<\\/i>\\u00a0<\\/p>\\n\\n\\n\\n<h2 class=\\\"wp-block-heading\\\">PPDS v7.1.59 (4\\/17\\/2025)&nbsp;<\\/h2>\\n\\n\\n\\n<figure class=\\\"wp-block-image is-resized image\\\"><img decoding=\\\"async\\\" src=\\\"https:\\/\\/info.prioritydispatch.net\\/l\\/1035463\\/2023-11-08\\/5v9d2k\\/1035463\\/1699480455dcdis9mg\\/IAEPD_Web_Asset_Headers.png\\\" alt=\\\"IAED Police Protocol Image\\\" style=\\\"aspect-ratio:3.2;width:800px;height:auto\\\"\\/><\\/figure>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">For a quick overview, <a target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" href=\\\"https:\\/\\/vimeo.com\\/1079561901\\/3bf92f66ca\\\">watch the PPDS v7.1.59 Highlight Reel<\\/a>.<\\/p>\\n\\n\\n\\n<h4 class=\\\"wp-block-heading\\\">Protocol 112: Deceased Person<\\/h4>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">A new Determinant Code and Key Question sequence have been added to handle \\u201cHospital report of death\\u201d incidents.<\\/p>\\n\\n\\n\\n<h4 class=\\\"wp-block-heading\\\">Protocol 127: Suicidal Person\\/Attempted Suicide\\/Suicide Ideation&nbsp;<\\/h4>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">This protocol has been extensively revised, including several new Determinant Codes, new and revised definitions, new suffixes, and a Special Definition for CRISIS TEAM \\/ ALTERNATE RESPONSE Criteria.<\\/p>\\n\\n\\n\\n<h4 class=\\\"wp-block-heading\\\">Protocol 131: Traffic Collision\\/Transportation Incident&nbsp;<\\/h4>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">This protocol has been extensively revised, including several new Determinant Codes, new Key Questions, new suffixes, and a Special Definition for MULTI-VEHICLE Pile-Up.<\\/p>\\n\\n\\n\\n<h4 class=\\\"wp-block-heading\\\">Protocol 132: Traffic Violation\\/Complaint\\/Hazard<\\/h4>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">A new Determinant Code and Key Question sequence have been added to handle \\u201cWrong-way travel\\u201d incidents.<br>&nbsp;<\\/p>\\n\\n\\n\\n<h2 class=\\\"wp-block-heading\\\">FPDS v8.0.836 (4\\/4\\/2025)<\\/h2>\\n\\n\\n\\n<figure class=\\\"wp-block-image is-resized image\\\"><img decoding=\\\"async\\\" src=\\\"https:\\/\\/info.prioritydispatch.net\\/l\\/1035463\\/2023-11-08\\/5v9d2n\\/1035463\\/1699480455vFz4ZGbB\\/IAEFD_Web_Asset_Headers.png\\\" alt=\\\"IAEFD Image of firefighters\\\" style=\\\"aspect-ratio:3.2;width:800px;height:auto\\\"\\/><\\/figure>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">For a quick overview, <a target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" href=\\\"https:\\/\\/vimeo.com\\/1079561246\\/2755e131a2\\\">watch the FPDS v8.0.836 Highlight Reel<\\/a>.<\\/p>\\n\\n\\n\\n<h4 class=\\\"wp-block-heading\\\">Protocol 54: Confined Space\\/Structure or Trench Collapse\\/ Sinkhole\\/ Landslide\\/Mudslide<\\/h4>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">Extensive updates have been made to split buildings from non-building structures, including changes to Determinant Codes, Sub-Chief Complaints, definitions, and answer choices.<\\/p>\\n\\n\\n\\n<h4 class=\\\"wp-block-heading\\\">Protocol 71: Vehicle Fire<\\/h4>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">A new Sub-Chief complaint, Determinant Code, and Key Question sequence have been added for e-bikes\\/e-scooters.<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">The new Key Question \\u201cIs this an electric vehicle (EV)?\\u201d will be asked for vehicles inside a parking garage, or other structure, prior to shunting to Protocol 69: Structure Fire.<\\/p>\\n\\n\\n\\n<h4 class=\\\"wp-block-heading\\\">Protocol 84: Structural Instability\\/Problems (Investigation)<\\/h4>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">This new ProQA-only protocol allows Fire agencies to better triage building and non-building structures that are currently unstable. It can be enabled or disabled in the Restricted Settings within the Admin Utility.<\\/p>\\n\\n\\n\\n<h2 class=\\\"wp-block-heading\\\">MPDS v14.0.406 (3\\/27\\/2025)<\\/h2>\\n\\n\\n\\n<figure class=\\\"wp-block-image is-resized image\\\"><img decoding=\\\"async\\\" src=\\\"https:\\/\\/info.prioritydispatch.net\\/l\\/1035463\\/2023-11-08\\/5v9d2r\\/1035463\\/1699480456ibcVeNpH\\/IAEMD_Web_Asset_Headers.png\\\" alt=\\\"IAED Medical Protocol Image\\\" style=\\\"aspect-ratio:3.2;width:800px;height:auto\\\"\\/><\\/figure>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">\\u00a0For a quick overview, <a href=\\\"https:\\/\\/vimeo.com\\/1079561772\\/c13a4195b6\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">watch the MPDS v14.0.406 Highlight Reel<\\/a>.<\\/p>\\n\\n\\n\\n<h4 class=\\\"wp-block-heading\\\">Case Entry<\\/h4>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">A new Chief Complaint Selection Rule has been added: \\u201cFor MEDICAL patients with a Chief Complaint of fainting (syncope) or near fainting (near syncopal episode and not fallen), go to Protocol 31. For patients who have expressed a fainting premonition (feels like fainting\\/might faint) as part of another foremost complaint, go to the protocol that best fits the foremost complaint.\\u201d<\\/p>\\n\\n\\n\\n<h4 class=\\\"wp-block-heading\\\">Protocol 9: Cardiac or Respiratory Arrest\\/Death, Protocol C: Airway\\/Arrest\\/Choking (Unconscious) &amp; Protocol YC: Tracheostomy (Stoma) Airway\\/Arrest\\/Choking (Unconscious)<\\/h4>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">Several adjustments were made to these protocols to accommodate a caller who is refusing to perform resuscitation\\/CPR on a patient, including patients the caller has reported as beyond any help.<\\/p>\\n\\n\\n\\n<h4 class=\\\"wp-block-heading\\\">Protocol 18: Headache &amp; Protocol 28: Stroke (CVA)\\/Transient Ischemic Attack (TIA)<\\/h4>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">The 18-C-3 and 28-C-3 Determinant Descriptors have been updated to \\u201cSudden speech, reading, or writing problems\\u201d. The STROKE Symptoms section has been updated, and a new Axiom has been added to support this change as well.<\\/p>\\n\\n\\n\\n<h4 class=\\\"wp-block-heading\\\">Protocol 24: Pregnancy\\/Childbirth\\/Miscarriage<\\/h4>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">A new Rule and Axiom have been added to better direct the EMD in how to handle multiple-birth situations.\\u00a0<\\/p>\\n\\n\\n\\n<h3 class=\\\"wp-block-heading\\\">HELP IS ON THE WAY: YOUR NEW REGIONAL CLIENT OUTREACH PROGRAM<\\/h3>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">Are you <strong>so many versions behind<\\/strong> in updating that you don&#8217;t know where to start?<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">Please reach out to your dedicated <a target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" href=\\\"https:\\/\\/prioritydispatch.widen.net\\/s\\/v9gdn5lhcq\\\"><strong>Regional Client Outreach representative<\\/strong><\\/a><strong> (RCO)<\\/strong> and let them help you with a plan to get current with ProQA and the latest protocols.<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\"><strong>Update Today. <\\/strong>Your Emergency Dispatchers, First Responders, and community need to be using the latest advancements in the protocols to meet the safety needs of our modern world.<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">We&#8217;re here to help you every step of the way.\\ufeff<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">Sincerely,<br>The <strong>International Academies of Emergency Dispatch and Priority Dispatch Corp.<\\/strong><\\/p>\\n\",\"protected\":false},\"excerpt\":{\"rendered\":\"<p>We&#8217;re pleased to be releasing a new version of the IAED&#8217;s Police Protocols, PPDS\\u00ae v7.1.59 (4\\/17\\/2025), with this ProQA v5.1.1.52 Maintenance Release. PPDS v7.1 includes extensive updates for suicidal calls and crisis team and alternative response criteria. We strongly encourage you to read the PPDS v7.1 Update Guide and watch the in-depth Update Presentation Video on the College to learn more abou<\\/p>\\n\",\"protected\":false},\"author\":1,\"featured_media\":0,\"comment_status\":\"open\",\"ping_status\":\"open\",\"sticky\":false,\"template\":\"\",\"format\":\"standard\",\"meta\":{\"_acf_changed\":false,\"footnotes\":\"\"},\"categories\":[26],\"tags\":[],\"class_list\":[\"post-828\",\"post\",\"type-post\",\"status-publish\",\"format-standard\",\"hentry\",\"category-protocol-updates\"],\"acf\":[],\"yoast_head\":\"<!-- This site is optimized with the Yoast SEO plugin v28.7 - https:\\/\\/yoast.com\\/product\\/yoast-seo-wordpress\\/ -->\\n<title>The IAED is Pleased to Announce PPDS v7.1.59 in the ProQA v5.1.1.52 Spring Maintenance Release | Emergency Dispatch<\\/title>\\n<meta name=\\\"robots\\\" content=\\\"noindex, follow, max-snippet:-1, max-image-preview:large, max-video-preview:-1\\\" \\/>\\n<meta property=\\\"og:locale\\\" content=\\\"en_US\\\" \\/>\\n<meta property=\\\"og:type\\\" content=\\\"article\\\" \\/>\\n<meta property=\\\"og:title\\\" content=\\\"The IAED is Pleased to Announce PPDS v7.1.59 in the ProQA v5.1.1.52 Spring Maintenance Release | Emergency Dispatch\\\" \\/>\\n<meta property=\\\"og:description\\\" content=\\\"We&#039;re pleased to be releasing a new version of the IAED&#039;s Police Protocols, PPDS\\u00ae v7.1.59 (4\\/17\\/2025), with this ProQA v5.1.1.52 Maintenance Release. PPDS v7.1 includes extensive updates for suicidal calls and crisis team and alternative response criteria. We strongly encourage you to read the PPDS v7.1 Update Guide and watch the in-depth Update Presentation Video on the College to learn more abou\\\" \\/>\\n<meta property=\\\"og:url\\\" content=\\\"https:\\/\\/emergencydistg.wpenginepowered.com\\/news\\/protocol-updates\\/BB2A8DC8-8472-46B5-A8A3-7854FA6D43FF\\/\\\" \\/>\\n<meta property=\\\"og:site_name\\\" content=\\\"Emergency Dispatch\\\" \\/>\\n<meta property=\\\"article:published_time\\\" content=\\\"2025-04-29T20:05:16+00:00\\\" \\/>\\n<meta property=\\\"article:modified_time\\\" content=\\\"2026-10-19T10:07:58+00:00\\\" \\/>\\n<meta property=\\\"og:image\\\" content=\\\"https:\\/\\/info.prioritydispatch.net\\/l\\/1035463\\/2025-04-21\\/5x34ft\\/1035463\\/1745253978mFKZTrQM\\/PPDS_v7_Email_Header.png\\\" \\/>\\n<meta name=\\\"author\\\" content=\\\"webdev@oozlemedia.com\\\" \\/>\\n<meta name=\\\"twitter:card\\\" content=\\\"summary_large_image\\\" \\/>\\n<meta name=\\\"twitter:label1\\\" content=\\\"Written by\\\" \\/>\\n\\t<meta name=\\\"twitter:data1\\\" content=\\\"webdev@oozlemedia.com\\\" \\/>\\n\\t<meta name=\\\"twitter:label2\\\" content=\\\"Est. reading time\\\" \\/>\\n\\t<meta name=\\\"twitter:data2\\\" content=\\\"5 minutes\\\" \\/>\\n<script type=\\\"application\\/ld+json\\\" class=\\\"yoast-schema-graph\\\">{\\\"@context\\\":\\\"https:\\\\\\/\\\\\\/schema.org\\\",\\\"@graph\\\":[{\\\"@type\\\":\\\"Article\\\",\\\"@id\\\":\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/news\\\\\\/protocol-updates\\\\\\/BB2A8DC8-8472-46B5-A8A3-7854FA6D43FF\\\\\\/#article\\\",\\\"isPartOf\\\":{\\\"@id\\\":\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/news\\\\\\/protocol-updates\\\\\\/BB2A8DC8-8472-46B5-A8A3-7854FA6D43FF\\\\\\/\\\"},\\\"author\\\":{\\\"name\\\":\\\"webdev@oozlemedia.com\\\",\\\"@id\\\":\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/#\\\\\\/schema\\\\\\/person\\\\\\/338f35ee363eca7c9019764391474b5a\\\"},\\\"headline\\\":\\\"The IAED is Pleased to Announce PPDS v7.1.59 in the ProQA v5.1.1.52 Spring Maintenance Release\\\",\\\"datePublished\\\":\\\"2025-04-29T20:05:16+00:00\\\",\\\"dateModified\\\":\\\"2026-10-19T10:07:58+00:00\\\",\\\"mainEntityOfPage\\\":{\\\"@id\\\":\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/news\\\\\\/protocol-updates\\\\\\/BB2A8DC8-8472-46B5-A8A3-7854FA6D43FF\\\\\\/\\\"},\\\"wordCount\\\":876,\\\"commentCount\\\":0,\\\"image\\\":{\\\"@id\\\":\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/news\\\\\\/protocol-updates\\\\\\/BB2A8DC8-8472-46B5-A8A3-7854FA6D43FF\\\\\\/#primaryimage\\\"},\\\"thumbnailUrl\\\":\\\"https:\\\\\\/\\\\\\/info.prioritydispatch.net\\\\\\/l\\\\\\/1035463\\\\\\/2025-04-21\\\\\\/5x34ft\\\\\\/1035463\\\\\\/1745253978mFKZTrQM\\\\\\/PPDS_v7_Email_Header.png\\\",\\\"articleSection\\\":[\\\"Protocol Updates\\\"],\\\"inLanguage\\\":\\\"en-US\\\",\\\"potentialAction\\\":[{\\\"@type\\\":\\\"CommentAction\\\",\\\"name\\\":\\\"Comment\\\",\\\"target\\\":[\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/news\\\\\\/protocol-updates\\\\\\/BB2A8DC8-8472-46B5-A8A3-7854FA6D43FF\\\\\\/#respond\\\"]}]},{\\\"@type\\\":\\\"WebPage\\\",\\\"@id\\\":\\