INSERT INTO `wp_ucm_queue` (`id`, `run_id`, `item_type`, `source_id`, `source_ref`, `title`, `priority`, `status`, `attempts`, `dest_id`, `message`, `payload`, `result`, `updated_at`) VALUES
(3890, 6, 'post', '874', 'https://emergencydistg.wpenginepowered.com/news/protocol-updates/EF3F4D7F-C2D1-4312-85DB-AD27B285DDF9', 'IAED Releases Version 4.2 Police Priority Dispatch Protocol', 50, 'done', 1, 1375, '', '{\"id\":874,\"date\":\"2014-07-30T00:00:00\",\"date_gmt\":\"2014-07-30T00:00:00\",\"guid\":{\"rendered\":\"https:\\/\\/emergencydistg.wpenginepowered.com\\/in-the-news\\/uncategorized\\/EF3F4D7F-C2D1-4312-85DB-AD27B285DDF9\\/\"},\"modified\":\"2026-10-19T06:38:54\",\"modified_gmt\":\"2026-10-19T06:38:54\",\"slug\":\"ef3f4d7f-c2d1-4312-85db-ad27b285ddf9\",\"status\":\"publish\",\"type\":\"post\",\"link\":\"https:\\/\\/emergencydistg.wpenginepowered.com\\/news\\/protocol-updates\\/EF3F4D7F-C2D1-4312-85DB-AD27B285DDF9\",\"title\":{\"rendered\":\"IAED Releases Version 4.2 Police Priority Dispatch Protocol\"},\"content\":{\"rendered\":\"\\n<p class=\\\"wp-block-paragraph\\\"><strong>SALT LAKE CITY<\\/strong>\\u2014May 12, 2014\\u2014The International Academy of Emergency Dispatch\\u2122 (IAED\\u2122) is pleased to announce the release of version 4.2 police protocols.<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">The new Police Priority Dispatch System\\u2122 (PPDS\\u00ae) version 4.2 protocols are designed to improve the speed and accuracy of the caller interrogation process. This update provides revisions that represent a continued desire to uphold and exceed a standard of excellence.<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">Proposals for Change (PFC) submitted by current users for the PPDS figure heavily into the recent update. PFCs are considered carefully and reviewed by the Police Council of Standards. Combining PFCs with current research and field expertise, the Council of Standards, on behalf of the College of Fellows, determines the proposals accepted and how they should be implemented.<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\"><strong>Protocol change highlights include:<\\/strong><\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">The suspect&#8217;s descriptive essentials template has been rearranged to more accurately collect information most commonly known to callers.<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">A major update of Protocol 131: Traffic\\/Transportation Incident (Crash) reduces the number of Key Questions by categorizing incidents into either Low Mechanism or High Mechanism and tailoring the interrogation to match either situation.<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">Changes to Protocol 105: Animal and Protocol 113: Disturbance\\/Nuisance also reflect the goal of eliminating unnecessary caller interrogation based on the sub-chief complaint chosen, and providing a more sensible Key Question pathway.<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">A Key Question to Protocol 135: Weapons\\/Firearms, &#8220;Have shots been fired?,&#8221; has been revised with two new sub-questions designed to gather more information if the caller has heard shots but didn&#8217;t see who fired them.<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">ProQA\\u00ae Paramount software is the exclusive operational system for PPDS v4.2.<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">These changes help decrease calltaking times, increase accuracy and efficiency, and enhance the user experience. For more information about ProQA Paramount or PPDS v4.2, go to <a href=\\\"https:\\/\\/www.prioritydispatch.net\\\" target=\\\"_blank\\\" rel=\\\"noreferrer\\\" class=\\\"inline-link\\\"><br> www.prioritydispatch.net<\\/a> or email <a href=\\\"mailto:epd.standards@emergencydispatch.org\\\" target=\\\"_blank\\\" rel=\\\"noreferrer\\\" class=\\\"inline-link\\\"><br> epd.standards@emergencydispatch.org<\\/a>.<\\/p>\\n\",\"protected\":false},\"excerpt\":{\"rendered\":\"<p>SALT LAKE CITY\\u2014May 12, 2014\\u2014The International Academy of<br \\/>\\nEmergency Dispatch\\u2122 (IAED\\u2122) is pleased to announce the release of<br \\/>\\nversion 4.2 police protocols. The new Police Priority Dispatch System\\u2122 (PPDS\\u00ae) version 4.2&#8230;<\\/p>\\n\",\"protected\":false},\"author\":1,\"featured_media\":0,\"comment_status\":\"open\",\"ping_status\":\"open\",\"sticky\":false,\"template\":\"\",\"format\":\"standard\",\"meta\":{\"_acf_changed\":false,\"footnotes\":\"\"},\"categories\":[26],\"tags\":[],\"class_list\":[\"post-874\",\"post\",\"type-post\",\"status-publish\",\"format-standard\",\"hentry\",\"category-protocol-updates\"],\"acf\":[],\"yoast_head\":\"<!-- This site is optimized with the Yoast SEO plugin v28.7 - https:\\/\\/yoast.com\\/product\\/yoast-seo-wordpress\\/ -->\\n<title>IAED Releases Version 4.2 Police Priority Dispatch Protocol | Emergency Dispatch<\\/title>\\n<meta name=\\\"robots\\\" content=\\\"noindex, follow, max-snippet:-1, max-image-preview:large, max-video-preview:-1\\\" \\/>\\n<meta property=\\\"og:locale\\\" content=\\\"en_US\\\" \\/>\\n<meta property=\\\"og:type\\\" content=\\\"article\\\" \\/>\\n<meta property=\\\"og:title\\\" content=\\\"IAED Releases Version 4.2 Police Priority Dispatch Protocol | Emergency Dispatch\\\" \\/>\\n<meta property=\\\"og:description\\\" content=\\\"SALT LAKE CITY\\u2014May 12, 2014\\u2014The International Academy of Emergency Dispatch\\u2122 (IAED\\u2122) is pleased to announce the release of version 4.2 police protocols. The new Police Priority Dispatch System\\u2122 (PPDS\\u00ae) version 4.2...\\\" \\/>\\n<meta property=\\\"og:url\\\" content=\\\"https:\\/\\/emergencydistg.wpenginepowered.com\\/news\\/protocol-updates\\/EF3F4D7F-C2D1-4312-85DB-AD27B285DDF9\\/\\\" \\/>\\n<meta property=\\\"og:site_name\\\" content=\\\"Emergency Dispatch\\\" \\/>\\n<meta property=\\\"article:published_time\\\" content=\\\"2014-07-30T00:00:00+00:00\\\" \\/>\\n<meta property=\\\"article:modified_time\\\" content=\\\"2026-10-19T06:38:54+00:00\\\" \\/>\\n<meta name=\\\"author\\\" content=\\\"webdev@oozlemedia.com\\\" \\/>\\n<meta name=\\\"twitter:card\\\" content=\\\"summary_large_image\\\" \\/>\\n<meta name=\\\"twitter:label1\\\" content=\\\"Written by\\\" \\/>\\n\\t<meta name=\\\"twitter:data1\\\" content=\\\"webdev@oozlemedia.com\\\" \\/>\\n\\t<meta name=\\\"twitter:label2\\\" content=\\\"Est. reading time\\\" \\/>\\n\\t<meta name=\\\"twitter:data2\\\" content=\\\"2 minutes\\\" \\/>\\n<script type=\\\"application\\/ld+json\\\" class=\\\"yoast-schema-graph\\\">{\\\"@context\\\":\\\"https:\\\\\\/\\\\\\/schema.org\\\",\\\"@graph\\\":[{\\\"@type\\\":\\\"Article\\\",\\\"@id\\\":\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/news\\\\\\/protocol-updates\\\\\\/EF3F4D7F-C2D1-4312-85DB-AD27B285DDF9\\\\\\/#article\\\",\\\"isPartOf\\\":{\\\"@id\\\":\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/news\\\\\\/protocol-updates\\\\\\/EF3F4D7F-C2D1-4312-85DB-AD27B285DDF9\\\\\\/\\\"},\\\"author\\\":{\\\"name\\\":\\\"webdev@oozlemedia.com\\\",\\\"@id\\\":\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/#\\\\\\/schema\\\\\\/person\\\\\\/338f35ee363eca7c9019764391474b5a\\\"},\\\"headline\\\":\\\"IAED Releases Version 4.2 Police Priority Dispatch Protocol\\\",\\\"datePublished\\\":\\\"2014-07-30T00:00:00+00:00\\\",\\\"dateModified\\\":\\\"2026-10-19T06:38:54+00:00\\\",\\\"mainEntityOfPage\\\":{\\\"@id\\\":\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/news\\\\\\/protocol-updates\\\\\\/EF3F4D7F-C2D1-4312-85DB-AD27B285DDF9\\\\\\/\\\"},\\\"wordCount\\\":294,\\\"commentCount\\\":0,\\\"articleSection\\\":[\\\"Protocol Updates\\\"],\\\"inLanguage\\\":\\\"en-US\\\",\\\"potentialAction\\\":[{\\\"@type\\\":\\\"CommentAction\\\",\\\"name\\\":\\\"Comment\\\",\\\"target\\\":[\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/news\\\\\\/protocol-updates\\\\\\/EF3F4D7F-C2D1-4312-85DB-AD27B285DDF9\\\\\\/#respond\\\"]}]},{\\\"@type\\\":\\\"WebPage\\\",\\\"@id\\\":\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/news\\\\\\/protocol-updates\\\\\\/EF3F4D7F-C2D1-4312-85DB-AD27B285DDF9\\\