INSERT INTO `wp_ucm_queue` (`id`, `run_id`, `item_type`, `source_id`, `source_ref`, `title`, `priority`, `status`, `attempts`, `dest_id`, `message`, `payload`, `result`, `updated_at`) VALUES
(3894, 6, 'post', '878', 'https://emergencydistg.wpenginepowered.com/news/protocol-updates/1095F3D3-D8F3-4B71-AB41-E8965D3712EE', 'Medical v12.1 Protocol', 50, 'done', 1, 1379, '', '{\"id\":878,\"date\":\"2010-04-01T00:00:00\",\"date_gmt\":\"2010-04-01T00:00:00\",\"guid\":{\"rendered\":\"https:\\/\\/emergencydistg.wpenginepowered.com\\/in-the-news\\/uncategorized\\/1095F3D3-D8F3-4B71-AB41-E8965D3712EE\\/\"},\"modified\":\"2026-10-19T06:33:42\",\"modified_gmt\":\"2026-10-19T06:33:42\",\"slug\":\"1095f3d3-d8f3-4b71-ab41-e8965d3712ee\",\"status\":\"publish\",\"type\":\"post\",\"link\":\"https:\\/\\/emergencydistg.wpenginepowered.com\\/news\\/protocol-updates\\/1095F3D3-D8F3-4B71-AB41-E8965D3712EE\",\"title\":{\"rendered\":\"Medical v12.1 Protocol\"},\"content\":{\"rendered\":\"\\n<p class=\\\"wp-block-paragraph\\\">The National Academies of Emergency Dispatch\\u00ae (NAED\\u2122) announces the release of version 12.1 of the Medical Priority Dispatch System\\u2122 (MPDS\\u00ae).<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">The release approved by the NAED&#8217;s Medical Council of Standards presents a significant revision to the world&#8217;s most trusted and widely used emergency medical dispatch protocol. Among other changes detailed below, version 12.1 introduces the Stroke Diagnostic Tool and Protocol 37: Interfacility Evaluation\\/Transfer.<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">The Stroke Diagnostic Tool, triggered in Protocol 28: Stroke (CVA) Key Questions, enables more accurate evaluation and identification of acute stroke patients. Twelve Determinant Suffixes added to Protocol 28 reflect the tool&#8217;s recommendation and aid in pinpointing specific symptoms most predictive of stroke.<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">Medical Council of Standards Co-Chair Marie Leroux said the Stroke Diagnostic Tool represents a significant life-saving prehospital tool for accurately identifying a stroke, and an essential tool when distinguishing patients suitable for immediate response without delay.<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">&#8220;The trick to helping these patients is identifying possible signs of a stroke within a very small window from onset,&#8221; Leroux said. &#8220;The EMD is a critical first link in the chain of recovery.&#8221;<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">The addition of Protocol 37 corresponds to requests for an interfacility transfer specific to medically-trained callers. The new protocol\\u2014already proven successful in Beta testing\\u2014is an alternative to Protocol 33 that allows dispatchers to minimize Key Questions regarding patient evaluation. Protocol 37 is only available in ProQA\\u00ae.<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">NAED Academics, Standards, &amp; Research Associate Brett Patterson said Protocol 37 represents the consensus of an expert sub-council that considered feedback obtained through an Academy survey answered by MPDS users internationally.<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">&#8220;The issue boiled down to two primary objectives,&#8221; Patterson said. &#8220;It was a matter of separating the routine transfer from the evaluation, and providing more response options for the trained EMD and health care professional to consider. Protocol 37 does this, and more.&#8221;<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">Other revisions in version 12.1 include an upgraded Aspirin Diagnostic and Instructions Tool, enhanced responder safety information, and earlier dispatch in certain circumstances.<\\/p>\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\">The NAED is a nonprofit association, headquartered in Salt Lake City, Utah, that specializes in the development of emergency communications center dispatch protocol.<\\/p>\\n\",\"protected\":false},\"excerpt\":{\"rendered\":\"<p>The National Academies of Emergency Dispatch\\u00ae (NAED\\u2122) announces the release of version 12.1 of the Medical Priority Dispatch System\\u2122 (MPDS\\u00ae). The release approved by the NAED&#8217;s Medical Council of Standards presents a significant&#8230;<\\/p>\\n\",\"protected\":false},\"author\":1,\"featured_media\":0,\"comment_status\":\"open\",\"ping_status\":\"open\",\"sticky\":false,\"template\":\"\",\"format\":\"standard\",\"meta\":{\"_acf_changed\":false,\"footnotes\":\"\"},\"categories\":[26],\"tags\":[],\"class_list\":[\"post-878\",\"post\",\"type-post\",\"status-publish\",\"format-standard\",\"hentry\",\"category-protocol-updates\"],\"acf\":[],\"yoast_head\":\"<!-- This site is optimized with the Yoast SEO plugin v28.7 - https:\\/\\/yoast.com\\/product\\/yoast-seo-wordpress\\/ -->\\n<title>Medical v12.1 Protocol | Emergency Dispatch<\\/title>\\n<meta name=\\\"robots\\\" content=\\\"noindex, follow, max-snippet:-1, max-image-preview:large, max-video-preview:-1\\\" \\/>\\n<meta property=\\\"og:locale\\\" content=\\\"en_US\\\" \\/>\\n<meta property=\\\"og:type\\\" content=\\\"article\\\" \\/>\\n<meta property=\\\"og:title\\\" content=\\\"Medical v12.1 Protocol | Emergency Dispatch\\\" \\/>\\n<meta property=\\\"og:description\\\" content=\\\"The National Academies of Emergency Dispatch\\u00ae (NAED\\u2122) announces the release of version 12.1 of the Medical Priority Dispatch System\\u2122 (MPDS\\u00ae). The release approved by the NAED&#039;s Medical Council of Standards presents a significant...\\\" \\/>\\n<meta property=\\\"og:url\\\" content=\\\"https:\\/\\/emergencydistg.wpenginepowered.com\\/news\\/protocol-updates\\/1095F3D3-D8F3-4B71-AB41-E8965D3712EE\\/\\\" \\/>\\n<meta property=\\\"og:site_name\\\" content=\\\"Emergency Dispatch\\\" \\/>\\n<meta property=\\\"article:published_time\\\" content=\\\"2010-04-01T00:00:00+00:00\\\" \\/>\\n<meta property=\\\"article:modified_time\\\" content=\\\"2026-10-19T06:33:42+00:00\\\" \\/>\\n<meta name=\\\"author\\\" content=\\\"webdev@oozlemedia.com\\\" \\/>\\n<meta name=\\\"twitter:card\\\" content=\\\"summary_large_image\\\" \\/>\\n<meta name=\\\"twitter:label1\\\" content=\\\"Written by\\\" \\/>\\n\\t<meta name=\\\"twitter:data1\\\" content=\\\"webdev@oozlemedia.com\\\" \\/>\\n\\t<meta name=\\\"twitter:label2\\\" content=\\\"Est. reading time\\\" \\/>\\n\\t<meta name=\\\"twitter:data2\\\" content=\\\"2 minutes\\\" \\/>\\n<script type=\\\"application\\/ld+json\\\" class=\\\"yoast-schema-graph\\\">{\\\"@context\\\":\\\"https:\\\\\\/\\\\\\/schema.org\\\",\\\"@graph\\\":[{\\\"@type\\\":\\\"Article\\\",\\\"@id\\\":\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/news\\\\\\/protocol-updates\\\\\\/1095F3D3-D8F3-4B71-AB41-E8965D3712EE\\\\\\/#article\\\",\\\"isPartOf\\\":{\\\"@id\\\":\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/news\\\\\\/protocol-updates\\\\\\/1095F3D3-D8F3-4B71-AB41-E8965D3712EE\\\\\\/\\\"},\\\"author\\\":{\\\"name\\\":\\\"webdev@oozlemedia.com\\\",\\\"@id\\\":\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/#\\\\\\/schema\\\\\\/person\\\\\\/338f35ee363eca7c9019764391474b5a\\\"},\\\"headline\\\":\\\"Medical v12.1 Protocol\\\",\\\"datePublished\\\":\\\"2010-04-01T00:00:00+00:00\\\",\\\"dateModified\\\":\\\"2026-10-19T06:33:42+00:00\\\",\\\"mainEntityOfPage\\\":{\\\"@id\\\":\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/news\\\\\\/protocol-updates\\\\\\/1095F3D3-D8F3-4B71-AB41-E8965D3712EE\\\\\\/\\\"},\\\"wordCount\\\":340,\\\"commentCount\\\":0,\\\"articleSection\\\":[\\\"Protocol Updates\\\"],\\\"inLanguage\\\":\\\"en-US\\\",\\\"potentialAction\\\":[{\\\"@type\\\":\\\"CommentAction\\\",\\\"name\\\":\\\"Comment\\\",\\\"target\\\":[\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/news\\\\\\/protocol-updates\\\\\\/1095F3D3-D8F3-4B71-AB41-E8965D3712EE\\\\\\/#respond\\\"]}]},{\\\"@type\\\":\\\"WebPage\\\",\\\"@id\\\":\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/news\\\\\\/protocol-updates\\\\\\/1095F3D3-D8F3-4B71-AB41-E8965D3712EE\\\\\\/\\\",\\\"url\\\":\\\