\\\\/78f3f0a0c1926ffac18f1d6e677dfe53866a9829e29e28b0c901eb48bc9dbad9?s=96&d=mm&r=g\\\",\\\"caption\\\":\\\"webdev@oozlemedia.com\\\"},\\\"sameAs\\\":[\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\"]}]}<\\/script>\\n<!-- \\/ Yoast SEO plugin. -->\",\"yoast_head_json\":{\"title\":\"The Invisible Heroes of the Fujian Provincial Emergency Center | Emergency Dispatch\",\"robots\":{\"index\":\"noindex\",\"follow\":\"follow\",\"max-snippet\":\"max-snippet:-1\",\"max-image-preview\":\"max-image-preview:large\",\"max-video-preview\":\"max-video-preview:-1\"},\"og_locale\":\"en_US\",\"og_type\":\"article\",\"og_title\":\"The Invisible Heroes of the Fujian Provincial Emergency Center | Emergency Dispatch\",\"og_description\":\"See how the Medical Priority Dispatch System is making a difference for the Fujian Provincial Emergency Center in Fuzhou, China.\",\"og_url\":\"https:\\/\\/emergencydistg.wpenginepowered.com\\/in-the-news\\/agency-news\\/9779856B-F26E-486E-803D-F8FE2AF493A5\\/\",\"og_site_name\":\"Emergency Dispatch\",\"article_published_time\":\"2025-03-21T16:07:18+00:00\",\"og_image\":[{\"url\":\"https:\\/\\/prioritydispatch.widen.net\\/content\\/zr7bws1345\\/jpeg\\/New%20Fujian%20Dispatchers.jpeg?w=800&amp;h=375&amp;keep=c&amp;crop=yes&amp;color=ffffffff&amp;quality=80&amp;u=wh2lld\",\"type\":\"\",\"width\":\"\",\"height\":\"\"}],\"author\":\"webdev@oozlemedia.com\",\"twitter_card\":\"summary_large_image\",\"twitter_misc\":{\"Written by\":\"webdev@oozlemedia.com\",\"Est. reading time\":\"8 minutes\"},\"schema\":{\"@context\":\"https:\\/\\/schema.org\",\"@graph\":[{\"@type\":\"Article\",\"@id\":\"https:\\/\\/emergencydistg.wpenginepowered.com\\/in-the-news\\/agency-news\\/9779856B-F26E-486E-803D-F8FE2AF493A5\\/#article\",\"isPartOf\":{\"@id\":\"https:\\/\\/emergencydistg.wpenginepowered.com\\/in-the-news\\/agency-news\\/9779856B-F26E-486E-803D-F8FE2AF493A5\\/\"},\"author\":{\"name\":\"webdev@oozlemedia.com\",\"@id\":\"https:\\/\\/emergencydistg.wpengine