INSERT INTO `wp_ucm_queue` (`id`, `run_id`, `item_type`, `source_id`, `source_ref`, `title`, `priority`, `status`, `attempts`, `dest_id`, `message`, `payload`, `result`, `updated_at`) VALUES
(3898, 6, 'post', '882', 'https://emergencydistg.wpenginepowered.com/news/agency-news/6BEFFE77-1260-4A83-9100-3B441F26435F', 'Dane County Report Explanation', 50, 'done', 1, 1383, '', '{\"id\":882,\"date\":\"2014-06-10T00:00:00\",\"date_gmt\":\"2014-06-10T00:00:00\",\"guid\":{\"rendered\":\"https:\\/\\/emergencydistg.wpenginepowered.com\\/in-the-news\\/uncategorized\\/6BEFFE77-1260-4A83-9100-3B441F26435F\\/\"},\"modified\":\"2026-10-16T10:01:29\",\"modified_gmt\":\"2026-10-16T10:01:29\",\"slug\":\"6beffe77-1260-4a83-9100-3b441f26435f\",\"status\":\"publish\",\"type\":\"post\",\"link\":\"https:\\/\\/emergencydistg.wpenginepowered.com\\/news\\/agency-news\\/6BEFFE77-1260-4A83-9100-3B441F26435F\",\"title\":{\"rendered\":\"Dane County Report Explanation\"},\"content\":{\"rendered\":\"\\n<img decoding=\\\"async\\\" src=\\\"https:\\/\\/prioritydispatch.widen.net\\/content\\/m1dhl3m7co\\/webp\\/Dane%20County%20ProQA%20call%20times.webp?w=1000&amp;position=c&amp;color=ffffffff&amp;quality=80&amp;u=7cbckq\\\">\\n\\n\\n\\n<p class=\\\"wp-block-paragraph\\\"><a target=\\\"_blank\\\" rel=\\\"noreferrer\\\" class=\\\"inline-link\\\"><\\/a><a href=\\\"https:\\/\\/prioritydispatch.widen.net\\/content\\/m1dhl3m7co\\/webp\\/Dane%20County%20ProQA%20call%20times.webp?w=1000&amp;position=c&amp;color=ffffffff&amp;quality=80&amp;u=7cbckq\\\" target=\\\"_blank\\\" rel=\\\"noopener\\\">This report<\\/a>, expertly created by Dane County, Wisconsin, is one of the first data sets to\\u00a0<strong>specifically identify the extent<\\/strong>\\u00a0of the effect that\\u00a0<strong>the<\\/strong>\\u00a0<strong>MPDS\\/FPDS\\/PPDS (ProQA) has in the total call-processing<\\/strong>\\u00a0<strong>timeframe<\\/strong>. This report depicts\\u00a0<strong>five call segments<\\/strong>\\u00a0contributing to their\\u00a0<strong>overall call processing and dispatching time<\\/strong>: 1.\\u00a0 Basic information\\u00a0<strong>(Address\\/Phone number &amp; verifications in CAD)<\\/strong>\\u00a02.\\u00a0 Protocol questions\\u00a0<strong>(ProQA Police, Fire, or Medical Protocols)<\\/strong>\\u00a03.\\u00a0 Transfer to dispatch\\u00a0<strong>(Calls received by CAD and waiting in queue for radio dispatchers to act on)<\\/strong>\\u00a04.\\u00a0 Unit selection\\u00a0<strong>(Unit recommendations by CAD)<\\/strong>\\u00a05.\\u00a0 Responders assigned\\u00a0<strong>(Units notified, but may not be en route yet)<\\/strong>\\u00a0On first examination,\\u00a0<strong>significantly extended times<\\/strong>\\u00a0are clearly identified in dispatch phases\\u00a0<strong>#1 \\u2013 Basic Information<\\/strong>\\u00a0and in\\u00a0<strong>#3 \\u2013 Transfer to dispatch<\\/strong>.\\u00a0There are\\u00a0<strong>minor<\\/strong>\\u00a0time extensions in phases \\u00a0<strong>#4 \\u2013 Unit Selection<\\/strong>\\u00a0and #<strong>5 \\u2013 Responders assigned<\\/strong>, as depicted when comparing &#8220;Madison Police&#8221; and &#8220;Other Police&#8221; (EPD) to &#8220;Fire&#8221; (EFD) and &#8220;EMS&#8221; (EMD) categories.\\u00a0<strong>Phase #2<\\/strong>\\u00a0represents (within the\\u00a0<strong>Emergent<\\/strong>,\\u00a0<strong>Urgent<\\/strong>, and\\u00a0<strong>Less<\\/strong>\\u00a0<strong>Urgent<\\/strong>\\u00a0groups shown), the\\u00a0<strong>actual ProQA questioning times<\\/strong>\\u00a0that are attributable to\\u00a0<strong>each of the Police, Fire, and Medical Priority Dispatch System&#8217;s protocols individually<\\/strong>, from start to the point that the ProQA recommended dispatch code is selected and CAD has simultaneously received this response-based code. \\u00a0 The IAED has offered its full expertise, and any on-site resources needed, to collaboratively analyze all associated 9-1-1 call data relative to call processing and dispatch times. \\u00a0<strong>We have identified several areas that contribute to the total calltaking time that might directly improve call processing.<\\/strong>\\u00a0\\u00a0The Academy has agreed to collaborate in identifying solutions to improve the services to the Dane County and Madison communities.\\u00a0<strong>Note:<\\/strong>\\u00a0the above\\u00a0<strong>blue font clarifiers<\\/strong>\\u00a0were added by IAED to further explain what is actually contained in each segment. IAED Research, Standards, &amp; Academics Division<\\/p>\\n\",\"protected\":false},\"excerpt\":{\"rendered\":\"<p>This report expertly created by Dane<br \\/>\\nCounty, Wisconsin, is one of the first data sets to specifically<br \\/>\\nidentify the extent of the effect that the MPDS\\/FPDS\\/PPDS<br \\/>\\n(ProQA) has in the total call-processing timeframe.<\\/p>\\n<p>This report depicts five call&#8230;<\\/p>\\n\",\"protected\":false},\"author\":1,\"featured_media\":0,\"comment_status\":\"open\",\"ping_status\":\"open\",\"sticky\":false,\"template\":\"\",\"format\":\"standard\",\"meta\":{\"_acf_changed\":false,\"footnotes\":\"\"},\"categories\":[27],\"tags\":[],\"class_list\":[\"post-882\",\"post\",\"type-post\",\"status-publish\",\"format-standard\",\"hentry\",\"category-agency-news\"],\"acf\":[],\"yoast_head\":\"<!-- This site is optimized with the Yoast SEO plugin v28.7 - https:\\/\\/yoast.com\\/product\\/yoast-seo-wordpress\\/ -->\\n<title>Dane County Report Explanation | Emergency Dispatch<\\/title>\\n<meta name=\\\"robots\\\" content=\\\"noindex, follow, max-snippet:-1, max-image-preview:large, max-video-preview:-1\\\" \\/>\\n<meta property=\\\"og:locale\\\" content=\\\"en_US\\\" \\/>\\n<meta property=\\\"og:type\\\" content=\\\"article\\\" \\/>\\n<meta property=\\\"og:title\\\" content=\\\"Dane County Report Explanation | Emergency Dispatch\\\" \\/>\\n<meta property=\\\"og:description\\\" content=\\\"This report expertly created by Dane County, Wisconsin, is one of the first data sets to specifically identify the extent of the effect that the MPDS\\/FPDS\\/PPDS (ProQA) has in the total call-processing timeframe. This report depicts five call...\\\" \\/>\\n<meta property=\\\"og:url\\\" content=\\\"https:\\/\