\\/\\\"},{\\\"@type\\\":\\\"ListItem\\\",\\\"position\\\":2,\\\"name\\\":\\\"Firefighters Recount Harrowing Rescue\\\"}]},{\\\"@type\\\":\\\"WebSite\\\",\\\"@id\\\":\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/#website\\\",\\\"url\\\":\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/\\\",\\\"name\\\":\\\"Emergency Dispatch\\\",\\\"description\\\":\\\"\\\",\\\"potentialAction\\\":[{\\\"@type\\\":\\\"SearchAction\\\",\\\"target\\\":{\\\"@type\\\":\\\"EntryPoint\\\",\\\"urlTemplate\\\":\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/?s={search_term_string}\\\"},\\\"query-input\\\":{\\\"@type\\\":\\\"PropertyValueSpecification\\\",\\\"valueRequired\\\":true,\\\"valueName\\\":\\\"search_term_string\\\"}}],\\\"inLanguage\\\":\\\"en-US\\\"},{\\\"@type\\\":\\\"Person\\\",\\\"@id\\\":\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\\\\/#\\\\\\/schema\\\\\\/person\\\\\\/338f35ee363eca7c9019764391474b5a\\\",\\\"name\\\":\\\"webdev@oozlemedia.com\\\",\\\"image\\\":{\\\"@type\\\":\\\"ImageObject\\\",\\\"inLanguage\\\":\\\"en-US\\\",\\\"@id\\\":\\\"https:\\\\\\/\\\\\\/secure.gravatar.com\\\\\\/avatar\\\\\\/78f3f0a0c1926ffac18f1d6e677dfe53866a9829e29e28b0c901eb48bc9dbad9?s=96&d=mm&r=g\\\",\\\"url\\\":\\\"https:\\\\\\/\\\\\\/secure.gravatar.com\\\\\\/avatar\\\\\\/78f3f0a0c1926ffac18f1d6e677dfe53866a9829e29e28b0c901eb48bc9dbad9?s=96&d=mm&r=g\\\",\\\"contentUrl\\\":\\\"https:\\\\\\/\\\\\\/secure.gravatar.com\\\\\\/avatar\\\\\\/78f3f0a0c1926ffac18f1d6e677dfe53866a9829e29e28b0c901eb48bc9dbad9?s=96&d=mm&r=g\\\",\\\"caption\\\":\\\"webdev@oozlemedia.com\\\"},\\\"sameAs\\\":[\\\"https:\\\\\\/\\\\\\/emergencydistg.wpenginepowered.com\\\"]}]}<\\/script>\\n<!-- \\/ Yoast SEO plugin. -->\",\"yoast_head_json\":{\"title\":\"Firefighters Recount Harrowing Rescue | Emergency Dispatch\",\"robots\":{\"index\":\"noindex\",\"follow\":\"follow\",\"max-snippet\":\"max-snippet:-1\",\"max-image-preview\":\"max-image-preview:large\",\"max-video-preview\":\"max-video-preview:-1\"},\"og_locale\":\"en_US\",\"og_type\":\"article\",\"og_title\":\"Firefighters Recount Harrowing Rescue | Emergency Dispatch\",\"og_description\":\"ROCHESTER -- It was a rescue that will never be forgotten by the nearly 60 firefighters and dozens of medical personnel who assisted the five people injured in Tuesday\'s early morning blaze. Many of the unsung heroes of the night agreed that the...\",\"og_url\":\"https:\\/\\/emergencydistg.wpenginepowered.com\\/news\\/agency-news\\/81114B8C-EB59-47D9-ABE5-EFD4E46A4A24\\/\",\"og_site_name\":\"Emergency Dispatch\",\"article_published_time\":\"2000-01-01T00:00:00+00:00\",\"article_modified_time\":\"2026-10-16T10:25:56+00:00\",\"author\":\"webdev@oozlemedia.com\",\"twitter_card\":\"summary_large_image\",\"twitter_misc\":{\"Written by\":\"webdev@oozlemedia.com\",\"Est. reading time\":\"7 minutes\"},\"schema\":{\"@context\":\"https:\\/\\/schema.org\",\"@graph\":[{\"@type\":\"Article\",\"@id\":\"https:\\/\\/emergencydistg.wpenginepowered.com\\/news\\/agency-news\\/81114B8C-EB59-47D9-ABE5-EFD4E46A4A24\\/#article\",\"isPartOf\":{\"@id\":\"https:\\/\\/emergencydistg.wpenginepowered.com\\/news\\/agency-news\\/81114B8C-EB59-47D9-ABE5-EFD4E46A4A24\\/\"},\"author\":{\"name\":\"webdev@oozlemedia.com\",\"@id\":\"https:\\/\\/emergencydistg.wpenginepowered.com\\/#\\/schema\\/person\\/338f35ee363eca7c9019764391474b5a\"},\"headline\":\"Firefighters Recount Harrowing Rescue\",\"datePublished\":\"2000-01-01T00:00:00+00:00\",\"dateModified\":\"2026-10-16T10:25:56+00:00\",\"mainEntityOfPage\":{\"@id\":\"https:\\/\\/emergencydistg.wpenginepowered.com\\/news\\/agency-news\\/81114B8C-EB59-47D9-ABE5-EFD4E46A4A24\\/\"},\"wordCount\":1565,\"commentCount\":0,\"articleSection\":[\"Agency News\"],\"inLanguage\":\"en-US\",\"potentialAction\":[{\"@type\":\"CommentAction\",\"name\":\"Comment\",\"target\":[\"https:\\/\\/emergencydistg.wpenginepowered.com\\/news\\/agency-news\\/81114B8C-EB59-47D9-ABE5-EFD4E46A4A24\\/#res